  VALUES (v_clase, 'encabezado', 9, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 10, '{"html":"<ol><li>American Diabetes Association Professional Practice Committee. 6. Glycemic Goals, Hypoglycemia, and Hyperglycemic Crises: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1):S132.</li><li>American Diabetes Association Professional Practice Committee. 13. Older Adults: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1):S277.</li><li>Cuenta de Alto Costo. Día mundial de la diabetes 2024 [Internet]. Bogotá: CAC; 14 nov 2024 [consultado 27 oct 2026]. Disponible en: <a href=\"https://cuentadealtocosto.org/noticias/dia-mundial-de-la-diabetes-2024/\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">https://cuentadealtocosto.org/noticias/dia-mundial-de-la-diabetes-2024/</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Algoritmo de tratamiento de la DM2 según ADA 2026: selección por comorbilidad', 'Clase 3 · Metas terapéuticas y selección del tratamiento', 4, 'video', 42, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Compara las opciones de primera línea e intensificación según enfermedad cardiovascular, insuficiencia cardiaca, enfermedad renal y obesidad.</p><p><strong>Objetivo:</strong> Comparar las opciones de tratamiento de la diabetes tipo 2 según las comorbilidades, de acuerdo con la sección 9 de ADA 2026.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=IqA9BjS6Q64","provider":"youtube","videoId":"IqA9BjS6Q64","title":"🔴 Actualización 2025: Guías ADA para la Diabetes  (Cambios Clave y Recomendaciones)","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>La ADA 2026 plantea el tratamiento con decisiones compartidas y centradas en la persona. Antes de mirar la HbA1c, se pregunta si hay enfermedad cardiovascular aterosclerótica (ECVA) o alto riesgo, insuficiencia cardiaca (IC), enfermedad renal crónica (ERC), obesidad o enfermedad hepática metabólica.</p><ul><li><strong>ECVA o alto riesgo:</strong> agonista GLP-1 y/o iSGLT2 con beneficio demostrado, independientemente de la HbA1c (recomendación 9.7).</li><li><strong>IC:</strong> iSGLT2 independientemente de la HbA1c (9.8). En obesidad con IC con fracción de eyección preservada sintomática, tirzepatida o un agonista GLP-1 con beneficio demostrado (9.9).</li><li><strong>ERC:</strong> iSGLT2 o agonista GLP-1 con beneficio demostrado (9.10). Con TFG &lt;30, se prefiere el agonista GLP-1 para el control glucémico (9.11).</li><li><strong>Sin estas condiciones:</strong> la metformina sigue siendo una opción inicial habitual, y puede considerarse terapia combinada desde el inicio para llegar antes a la meta (9.6).</li></ul><p>Al agregar un fármaco se revisan las dosis de sulfonilureas, meglitinidas e insulina para reducir hipoglucemias (9.17). No se combina un iDPP-4 con un agonista GLP-1 o con tirzepatida (9.18). Si hay hiperglucemia sintomática, HbA1c &gt;10 % o glucosa ≥300 mg/dL, se considera insulina (9.20); sin hiperglucemia grave, la terapia basada en GLP-1 se prefiere a la insulina (9.21).</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una mujer de 58 años en Bucaramanga, con infarto hace dos años, HbA1c 7,8 % y TFG de 72 mL/min, toma metformina 850 mg cada 12 horas. Aunque está cerca de la meta, el QF anota en la revisión de la fórmula que, por su ECVA, la guía recomienda añadir un agonista GLP-1 o un iSGLT2 con beneficio cardiovascular, y lo comunica al médico tratante.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>Primero se evalúan las comorbilidades (ECVA, IC, ERC, obesidad) y luego la HbA1c.</li><li>iSGLT2 y agonistas GLP-1 se indican por beneficio cardiorrenal, sin importar la HbA1c.</li><li>No combinar iDPP-4 con agonistas GLP-1; revisar secretagogos e insulina al intensificar.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 6, '{"text":"Para profundizar","level":2}'::jsonb);
