  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>American Diabetes Association Professional Practice Committee. 9. Pharmacologic Approaches to Glycemic Treatment: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1):S183-S215. <a href=\"https://doi.org/10.2337/dc26-S009\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.2337/dc26-S009</a></li><li>Ministerio de Salud y Protección Social, Colciencias. Guía de práctica clínica para el diagnóstico, tratamiento y seguimiento de la diabetes mellitus tipo 2 en la población mayor de 18 años. Bogotá: MinSalud; 2016.</li><li>Kotwal SS, Perkovic V. Effects of Semaglutide on CKD in Patients With Type 2 Diabetes. Kidney Int Rep. 2025;10:287-90. <a href=\"https://doi.org/10.1016/j.ekir.2024.11.1365\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.ekir.2024.11.1365</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Caso: evaluación inicial de una persona con DM2 recién diagnosticada y albuminuria', 'Clase 3 · Metas terapéuticas y selección del tratamiento', 5, 'manual', 98, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta la evaluación farmacoterapéutica inicial de un paciente con DM2 nueva, albuminuria y riesgo cardiovascular.</p><p><strong>Objetivo:</strong> Ejecutar la evaluación farmacoterapéutica inicial de una persona con diabetes tipo 2 recién diagnosticada.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=RZl706hlNa0","provider":"youtube","videoId":"RZl706hlNa0","title":"Revisión: American Diabetes Association Standards of Care in Diabetes 2025; PARTE 2","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Don Jairo tiene 49 años y es conductor de bus en Pereira. Fuma, tiene IMC de 33 kg/m² y presión de 138/86 mmHg. Sus exámenes: HbA1c 8,4 %, glucosa en ayunas 172 mg/dL, TFG 88 mL/min y relación albúmina/creatinina 45 mg/g. No tiene enfermedad cardiovascular conocida. El médico inicia metformina 850 mg cada 12 horas con las comidas.</p><p>El QF sigue estos pasos:</p><ol><li><strong>Verifica el diagnóstico y acuerda la meta:</strong> HbA1c &lt;7 % sin hipoglucemia.</li><li><strong>Identifica comorbilidades:</strong> la albuminuria moderada (30 a 299 mg/g), si se confirma en otra muestra, indica enfermedad renal crónica. ADA 2026 recomienda en ERC un iSGLT2 o un agonista GLP-1 con beneficio demostrado (9.10), además de la metformina.</li><li><strong>Revisa la metformina:</strong> según la ficha técnica, se inicia con 500 u 850 mg dos o tres veces al día, durante o después de las comidas, y se ajusta a los 10-15 días; subir la dosis lentamente mejora la tolerancia. Con TFG ≥60 no hay restricción renal, pero la TFG se vigila al menos una vez al año.</li><li><strong>Educa:</strong> tomar con comidas, molestias digestivas iniciales, evitar el exceso de alcohol y suspender temporalmente si hay deshidratación (vómito o diarrea intensos) y consultar.</li><li><strong>Registra y remite:</strong> propone al médico la confirmación de la albuminuria y la valoración de un iSGLT2 o agonista GLP-1, la evaluación de estatina y presión arterial, y apoyo para dejar de fumar.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>El QF documenta en formato SOAP. S: \"me da miedo la insulina\". O: HbA1c 8,4 %, RAC 45 mg/g, IMC 33. A: DM2 de diagnóstico reciente con probable ERC por albuminuria y obesidad; tratamiento sin protección renal. P: educación en metformina, nota al médico con la recomendación 9.10 de ADA 2026 y control de HbA1c en 3 meses.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>Toda evaluación inicial incluye meta, comorbilidades cardiorrenales y función renal.</li><li>La albuminuria cambia la elección del tratamiento, aunque la TFG sea normal.</li><li>La educación al iniciar metformina mejora la tolerancia y la adherencia.</li></ol>"}'::jsonb);
