  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Sulfonilureas y pioglitazona: eficacia, hipoglucemia, peso y desintensificación', 'Clase 3 · iDPP-4, sulfonilureas y pioglitazona', 4, 'video', 11, TRUE)
