  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Compara las sulfonilureas y la pioglitazona en eficacia, riesgo de hipoglucemia, peso y seguridad cardiovascular.</p><p><strong>Objetivo:</strong> Comparar sulfonilureas y pioglitazona y reconocer cuándo conviene revisarlas o desintensificarlas.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=duCUmL7Hruo","provider":"youtube","videoId":"duCUmL7Hruo","title":"GLIBENCLAMIDA, lo esencial. ¿Tratamiento para la diabetes?","transcriptHtml":""}'::jsonb);
