  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Caso: adulto mayor con ERC en tratamiento con metformina y glibenclamida', 'Clase 3 · iDPP-4, sulfonilureas y pioglitazona', 5, 'video', 74, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta la revisión de la medicación de un adulto mayor con caída de la TFG, hipoglucemias y uso prolongado de metformina.</p><p><strong>Objetivo:</strong> Ejecutar la revisión de la farmacoterapia de un adulto mayor con enfermedad renal crónica, hipoglucemias y tratamiento oral clásico.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=_UnvGSfKT8I","provider":"youtube","videoId":"_UnvGSfKT8I","title":"Guia Diabetes Care 2025","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Don Aurelio tiene 76 años y vive en Sogamoso. Tiene diabetes tipo 2 hace 15 años e hipertensión. Toma metformina 850 mg cada 8 horas, glibenclamida 5 mg cada 12 horas, losartán 50 mg/día e ibuprofeno a necesidad para dolor de rodilla. Sus exámenes: HbA1c 6,6 %, TFG 38 mL/min, relación albúmina/creatinina 120 mg/g y hemoglobina 11,2 g/dL con volumen corpuscular alto. Refiere dos episodios de mareo y sudoración en el último mes y hormigueo en los pies.</p><p>El QF sigue estos pasos:</p><ol><li><strong>Metformina:</strong> con TFG 30-44 la ficha técnica fija un máximo de 1.000 mg/día; recibe 2.550 mg. Recomienda reducir la dosis y vigilar la TFG cada 3-6 meses.</li><li><strong>Glibenclamida:</strong> episodios compatibles con hipoglucemia, edad avanzada y ERC. Recomienda suspenderla y revisar la meta individual (por ejemplo, HbA1c &lt;8 %).</li><li><strong>Protección renal:</strong> por ERC con albuminuria, ADA 2026 recomienda un iSGLT2 o un agonista GLP-1 con beneficio demostrado; lo propone al médico.</li><li><strong>Ibuprofeno:</strong> los AINE pueden deteriorar la función renal, más con losartán y metformina; sugiere alternativas para el dolor.</li><li><strong>Vitamina B12:</strong> anemia con volumen alto y parestesias tras años de metformina; sugiere medir la B12.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>El QF registra en SOAP. S: mareos y sudoración, hormigueo en pies. O: TFG 38, RAC 120, HbA1c 6,6 %, Hb 11,2. A: dosis de metformina excesiva para la TFG, hipoglucemia probable por glibenclamida, AINE con riesgo renal, posible déficit de B12, sin protección cardiorrenal. P: nota al médico con cinco recomendaciones, educación en hipoglucemia y control en 4 semanas.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>La revisión de la medicación se hace con la TFG actual, no con la del inicio del tratamiento.</li><li>En adultos mayores con hipoglucemias, desintensificar es una intervención de seguridad.</li><li>Los AINE, la anemia y las parestesias también son parte del análisis del QF.</li></ol>"}'::jsonb);
