  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 11, '{"url":"https://www.invima.gov.co/alertas-sanitarias/ozempic-134-mgml-semaglutida-lotes-lp6f832-mp5e511-nar0074-np5g443","title":"Alerta sanitaria INVIMA No. 200-2024: falsificación de OZEMPIC 1,34 mg/mL (lotes LP6F832, MP5E511, NAR0074, NP5G443) (2024-07-02)","description":"Documento · Documento oficial · autoridad sanitaria"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 12, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 13, '{"html":"<ol><li>AEMPS/EMA. Ficha técnica Ozempic (semaglutida) solución inyectable. CIMA [consultado 27 oct 2026].</li><li>Kotwal SS, Perkovic V. Effects of Semaglutide on CKD in Patients With Type 2 Diabetes. Kidney Int Rep. 2025;10:287-90. <a href=\"https://doi.org/10.1016/j.ekir.2024.11.1365\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.ekir.2024.11.1365</a></li><li>Organización Mundial de la Salud. Semaglutide medicines and non-arteritic anterior ischemic optic neuropathy (NAION). Ginebra: OMS; 27 jun 2025.</li><li>European Medicines Agency. Meeting highlights from the Pharmacovigilance Risk Assessment Committee (PRAC) 8-11 April 2024. Amsterdam: EMA; 12 abr 2024.</li><li>Instituto Nacional de Vigilancia de Medicamentos y Alimentos (INVIMA). Alerta sanitaria No. 200-2024: OZEMPIC 1,34 mg/mL (semaglutida), lotes LP6F832, MP5E511, NAR0074, NP5G443. Bogotá: INVIMA; 2 jul 2024.</li></ol>"}'::jsonb);
