  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=OCjOaAHqfAQ","provider":"youtube","videoId":"OCjOaAHqfAQ","title":"Tirzepatida y GLP-1: qué son, cuándo usarlos y qué diferencias hay","transcriptHtml":""}'::jsonb);
