  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>American Diabetes Association Professional Practice Committee. 9. Pharmacologic Approaches to Glycemic Treatment: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1):S183-S215. <a href=\"https://doi.org/10.2337/dc26-S009\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.2337/dc26-S009</a></li><li>American Diabetes Association Professional Practice Committee. 10. Cardiovascular Disease and Risk Management: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1):S216.</li><li>Kotwal SS, Perkovic V. Effects of Semaglutide on CKD in Patients With Type 2 Diabetes. Kidney Int Rep. 2025;10:287-90. <a href=\"https://doi.org/10.1016/j.ekir.2024.11.1365\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.ekir.2024.11.1365</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Caso: inicio de iSGLT2 y agonista GLP-1 en una persona con insuficiencia cardiaca, ERC e insulina', 'Clase 4 · Selección del tratamiento y caso', 7, 'video', 8, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta un plan de inicio y seguimiento de dapagliflozina y semaglutida, con ajuste de insulina y educación en días de enfermedad.</p><p><strong>Objetivo:</strong> Ejecutar el plan farmacoterapéutico al iniciar un iSGLT2 y un agonista GLP-1 en una persona con comorbilidad cardiorrenal y uso de insulina.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=WwUFDpwfr1A","provider":"youtube","videoId":"WwUFDpwfr1A","title":"SGLT2 (empagliflozina, dapagliflozina): beneficios, riesgos y cuándo utilizarlos","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Doña Marlene tiene 63 años y vive en Santa Marta. Tiene diabetes tipo 2 hace 12 años, insuficiencia cardiaca con fracción de eyección reducida, TFG de 48 mL/min, relación albúmina/creatinina 210 mg/g, IMC 34 kg/m² y HbA1c 8,6 %. Recibe metformina 500 mg cada 12 horas, insulina glargina 30 UI en la noche, furosemida 40 mg/día y enalapril. Su médico inicia dapagliflozina 10 mg/día y planea semaglutida semanal.</p><p>El QF sigue estos pasos:</p><ol><li><strong>Verifica la indicación:</strong> iSGLT2 por insuficiencia cardiaca (9.8) y ERC con albuminuria (9.10); agonista GLP-1 por obesidad y control glucémico.</li><li><strong>Riesgo de hipoglucemia:</strong> con insulina, la ficha técnica de ambos fármacos sugiere considerar reducir la dosis de insulina; propone al médico disminuir la glargina y reforzar la glucometría.</li><li><strong>Volumen:</strong> con furosemida hay más riesgo de deshidratación e hipotensión; sugiere vigilar peso, presión y síntomas.</li><li><strong>Titulación de semaglutida:</strong> 0,25 mg semanal por 4 semanas, luego 0,5 mg; educa sobre náuseas y porciones pequeñas.</li><li><strong>Días de enfermedad:</strong> si hay vómito, diarrea, fiebre o no puede comer, suspender temporalmente dapagliflozina y metformina y consultar; aprender las señales de cetoacidosis aunque la glucosa no esté muy alta.</li><li><strong>Seguimiento:</strong> TFG y potasio en 2-4 semanas (es esperable una caída inicial leve de la TFG), HbA1c en 3 meses.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>El QF registra la intervención en la historia farmacoterapéutica, entrega la tarjeta de días de enfermedad y programa una llamada a las 2 semanas. En la llamada, Marlene refiere dos glucometrías de 65 mg/dL en ayunas; el QF lo comunica y el médico reduce de nuevo la glargina.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>Al iniciar iSGLT2 o agonista GLP-1 con insulina, anticipar la reducción de insulina.</li><li>Con diuréticos de asa, vigilar la volemia al iniciar un iSGLT2.</li><li>Las reglas de días de enfermedad son parte obligatoria de la educación.</li></ol>"}'::jsonb);
