  VALUES (v_clase, 'enlace', 9, '{"url":"https://www.invima.gov.co/alertas-sanitarias/minimed-640g-insulin-pump-bomba-de-insulina-minimed-670g-bomba-de-insulina-minimed-780g-insulin-pump-bomba-de-insulina-m","title":"Alerta sanitaria INVIMA No. 042-2025: bombas de insulina MiniMed 640G / 670G / 780G (2025)","description":"Documento · Documento oficial · autoridad sanitaria"}'::jsonb);
