  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Hipoglucemia: clasificación, regla de los 15, glucagón y prevención', 'Clase 4 · Hipoglucemia y caso', 6, 'video', 12, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Aplica la clasificación y el tratamiento de la hipoglucemia y las medidas de prevención en la educación al paciente.</p><p><strong>Objetivo:</strong> Aplicar la clasificación, el tratamiento y la prevención de la hipoglucemia en la atención farmacéutica.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=FOJjxOzg6Yc","provider":"youtube","videoId":"FOJjxOzg6Yc","title":"Hipoglucemias, ¿Qué son?, ¿Cómo corregirlas? y la regla del 15. Marifé Durán. Endocrino en Red.","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>La ADA clasifica la hipoglucemia en tres niveles. Nivel 1: glucosa menor de 70 mg/dL y mayor o igual a 54 mg/dL. Nivel 2: menor de 54 mg/dL, valor que requiere acción inmediata. Nivel 3 (grave): evento con alteración mental o física que necesita ayuda de otra persona, sin importar el valor de glucosa. Los síntomas incluyen temblor, sudoración, palpitaciones, hambre, ansiedad, confusión, visión borrosa y, en casos graves, convulsiones o pérdida de conciencia. Algunas personas, sobre todo con diabetes de larga evolución o hipoglucemias repetidas, no perciben los síntomas.</p><p><strong>Tratamiento en la persona consciente (regla de los 15):</strong> tomar 15 a 20 g de glucosa o de carbohidratos de absorción rápida (por ejemplo, tabletas de glucosa, azúcar disuelta en agua o medio vaso de jugo o gaseosa no dietética), esperar 15 minutos y volver a medir. Si sigue baja, repetir. Cuando se normalice, comer algo para evitar que vuelva. La ADA indica que debe formularse glucagón a toda persona con riesgo de hipoglucemia nivel 2 o 3, y que familiares o cuidadores aprendan a usarlo. En la persona inconsciente no se da nada por la boca: se usa glucagón si está disponible y se busca atención urgente.</p><p><strong>Causas a revisar:</strong> dosis excesiva de insulina o sulfonilurea, comida omitida o retrasada, ejercicio no planificado, alcohol, enfermedad renal o pérdida de peso que reduce las necesidades. Las sulfonilureas y la insulina son los fármacos con mayor riesgo; al agregar un agonista GLP-1, tirzepatida o un iSGLT2 se reevalúa su dosis.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un conductor de taxi de Barranquilla con glimepirida e insulina refiere temblor y sudor al manejar. El QF le enseña la regla de los 15, a medir la glucosa antes de conducir, a llevar siempre azúcar o tabletas de glucosa, e informa al médico para revisar la dosis.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li><strong>Nivel 1:</strong> &lt;70 mg/dL; nivel 2: &lt;54 mg/dL; nivel 3: requiere ayuda de otra persona.</li><li><strong>Regla de los 15:</strong> 15-20 g de glucosa, medir a los 15 minutos y repetir si sigue baja.</li><li>Toda hipoglucemia es una señal para revisar el tratamiento.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
