  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>American Diabetes Association Professional Practice Committee. 10. Cardiovascular Disease and Risk Management: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1):S216.</li><li>American Diabetes Association Professional Practice Committee. 9. Pharmacologic Approaches to Glycemic Treatment: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1):S183-S215. <a href=\"https://doi.org/10.2337/dc26-S009\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.2337/dc26-S009</a></li><li>Alam A. Tirzepatide versus Dulaglutide in Type 2 Diabetes Mellitus: Cardiovascular Insights from SURPASS-CVOT and Relevance to South Asian Populations. Bangladesh J Endocrinol Metab. 2026;5:218-20. <a href=\"https://doi.org/10.4103/bjem.bjem_11_26\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.4103/bjem.bjem_11_26</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Enfermedad renal crónica y diabetes: tamizaje, nefroprotección y ajuste de antidiabéticos', 'Clase 2 · Comorbilidad cardiorrenal y obesidad', 2, 'video', 9, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Aplica el tamizaje con TFG y albuminuria, las terapias nefroprotectoras y el ajuste de antidiabéticos según la función renal.</p><p><strong>Objetivo:</strong> Aplicar el tamizaje, la nefroprotección y el ajuste de antidiabéticos en la persona con diabetes y enfermedad renal crónica (ERC).</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=KbEoYPmvVDw","provider":"youtube","videoId":"KbEoYPmvVDw","title":"🫀 HIPERTENSIÓN y DAÑO RENAL: Guía KDIGO 2024 (Presión menor 120 mmHg y Fármacos)","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p><strong>Tamizaje:</strong> la ADA recomienda medir al menos una vez al año la tasa de filtración glomerular (TFG) y la relación albúmina/creatinina en orina (RAC). La ERC se confirma si las alteraciones persisten más de 3 meses. La RAC de 30 a 299 mg/g indica albuminuria moderada y de 300 mg/g o más, albuminuria grave.</p><p>Pilares de la nefroprotección según ADA 2026:</p><ul><li>Control de la presión arterial y de la glucosa.</li><li>IECA o ARA II en hipertensión con albuminuria, a la dosis máxima tolerada, vigilando creatinina y potasio.</li><li>iSGLT2 con beneficio demostrado para frenar la progresión de la ERC y reducir eventos cardiovasculares. La ADA los recomienda desde TFG de 20 mL/min; la ficha técnica europea de dapagliflozina no recomienda iniciarla con TFG menor de 25. En Colombia se sigue el inserto INVIMA.</li><li><strong>Agonista GLP-1 con beneficio demostrado:</strong> la semaglutida redujo eventos renales mayores y muerte cardiovascular en el estudio FLOW. Con TFG menor de 30, el agonista GLP-1 es el antidiabético preferido (9.11).</li><li>Finerenona (antagonista no esteroideo del receptor de mineralocorticoides) en personas con albuminuria y potasio normal, para reducir progresión renal y eventos cardiovasculares.</li></ul><p><strong>Ajuste de antidiabéticos:</strong> metformina, máximo 1.000 mg/día con TFG 30-44 y contraindicada con TFG menor de 30; la mayoría de iDPP-4 requieren ajuste (no la linagliptina); las sulfonilureas aumentan el riesgo de hipoglucemia; la insulina suele requerir menos dosis; semaglutida y tirzepatida no requieren ajuste, con precaución en insuficiencia renal grave.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una paciente de Tuluá con diabetes tipo 2, TFG de 42 mL/min y RAC de 350 mg/g toma metformina 850 mg cada 8 horas y losartán 50 mg. El QF propone al médico reducir la metformina a máximo 1.000 mg/día, optimizar el losartán según tolerancia y agregar un iSGLT2; además, vigilar el potasio si se considera finerenona.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li><strong>Tamizaje anual con TFG y RAC:</strong> la albuminuria es tan importante como la TFG.</li><li>IECA/ARA II, iSGLT2, agonista GLP-1 con beneficio y finerenona son los pilares farmacológicos.</li><li>Revisar dosis de metformina, iDPP-4, sulfonilureas e insulina en cada cambio de TFG.</li></ol>"}'::jsonb);
