  VALUES (v_clase, 'encabezado', 11, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 12, '{"html":"<ol><li>American Diabetes Association Professional Practice Committee. 8. Obesity and Weight Management for the Prevention and Treatment of Diabetes: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1):S166.</li><li>Agencia Europea de Medicamentos. Saxenda (liraglutida): ficha técnica o resumen de las características del producto. EMA; EPAR actualizado 31 jul 2025.</li><li>AEMPS/EMA. Ficha técnica Mounjaro (tirzepatida) solución inyectable. CIMA [consultado 27 oct 2026].</li><li>Instituto Nacional de Vigilancia de Medicamentos y Alimentos (INVIMA). Alerta sanitaria No. 090-2024: Semaglutida + B12. Bogotá: INVIMA; 11 abr 2024.</li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Seguimiento farmacoterapéutico de la persona con diabetes en el servicio farmacéutico colombiano', 'Clase 3 · Seguimiento farmacoterapéutico, farmacovigilancia y caso integrador', 4, 'video', 42, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Aplica el proceso de seguimiento farmacoterapéutico, la identificación de problemas relacionados con medicamentos y los indicadores de resultado.</p><p><strong>Objetivo:</strong> Aplicar el proceso de seguimiento farmacoterapéutico (SFT) a personas con diabetes dentro del servicio farmacéutico.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=2iNCaGrgChw","provider":"youtube","videoId":"2iNCaGrgChw","title":"Farmacia Comunitaria. Actividades orientadas al Paciente. Seguimiento Farmacoterapéutico. Vídeo 3","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>En Colombia, el servicio farmacéutico está regulado por el Decreto 780 de 2016, que compila las normas del sector, y por la Resolución 1403 de 2007, que adopta el Modelo de Gestión del Servicio Farmacéutico. Este modelo incluye la atención farmacéutica y el seguimiento farmacoterapéutico como procesos para mejorar los resultados de los medicamentos en el paciente.</p><p>El SFT es un proceso sistemático y documentado. Un esquema práctico, basado en el método Dáder, incluye:</p><ol><li><strong>Oferta del servicio y primera entrevista:</strong> problemas de salud, medicamentos (incluidos los de venta libre y productos naturales), forma de uso y preocupaciones.</li><li><strong>Estado de situación:</strong> relacionar cada problema de salud con su medicamento y los parámetros de control.</li><li><strong>Estudio y evaluación:</strong> identificar problemas relacionados con medicamentos (PRM) y resultados negativos asociados a la medicación (RNM) de necesidad, efectividad y seguridad.</li><li><strong>Intervención:</strong> con el paciente (educación) o con el médico (propuesta escrita).</li><li><strong>Entrevistas sucesivas:</strong> verificar el resultado de cada intervención.</li></ol><p><strong>En diabetes, los PRM más frecuentes son:</strong> dosis no ajustada a la función renal, duplicidades o combinaciones no recomendadas (iDPP-4 con agonista GLP-1), hipoglucemias por sulfonilureas o insulina, técnica de inyección incorrecta, mala conservación, falta de indicación cardiorrenal (iSGLT2 o agonista GLP-1) y baja adherencia. Indicadores de resultado: HbA1c, tiempo en rango si hay MCG, número de hipoglucemias, presión arterial, LDL, TFG y RAC, peso y adherencia.</p><p>Las revisiones sistemáticas recientes sobre intervenciones lideradas por farmacéuticos muestran mejoras en el control glucémico y en la seguridad del tratamiento.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>En una farmacia ambulatoria de Bogotá, el QF hace SFT a 40 pacientes con HbA1c mayor de 9 %. En la primera entrevista identifica que el 30 % no usaba bien la pluma de insulina y que varios tomaban la metformina en ayunas por \"miedo a que no funcione con comida\". Interviene con educación y propuestas al médico, y repite la HbA1c a los 3 meses.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>El SFT es un proceso documentado, respaldado por la Resolución 1403 de 2007.</li><li>Los PRM se clasifican por necesidad, efectividad y seguridad, y cada intervención se verifica.</li><li>Medir indicadores (HbA1c, hipoglucemias, TFG, RAC, adherencia) permite demostrar el impacto del QF.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 6, '{"text":"Para profundizar","level":2}'::jsonb);
