  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 9, '{"url":"https://doi.org/10.1007/s13410-026-01667-2","title":"Jaya MKA, Rahmawati F, Yasin NM, Ikawati Z. Pharmacist-led interventions for optimizing type 2 diabetes mellitus management and medication safety in Southeast Asian countries: a systematic review and","description":"Artículo científico · DOI 10.1007/s13410-026-01667-2"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 10, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>Ministerio de la Protección Social. Resolución 1403 de 2007, por la cual se determina el Modelo de Gestión del Servicio Farmacéutico y se adopta el Manual de Condiciones Esenciales y Procedimientos. Bogotá; 2007.</li><li>Ministerio de Salud y Protección Social. Decreto 780 de 2016, Decreto Único Reglamentario del Sector Salud y Protección Social. Bogotá; 2016.</li><li>Jaya MKA, Rahmawati F, Yasin NM, Ikawati Z. Pharmacist-led interventions for optimizing type 2 diabetes mellitus management and medication safety in Southeast Asian countries: a systematic review and meta-analysis. Int J Diabetes Dev Ctries. 2026;46(3):664-85. <a href=\"https://doi.org/10.1007/s13410-026-01667-2\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1007/s13410-026-01667-2</a></li><li>American Diabetes Association Professional Practice Committee. 9. Pharmacologic Approaches to Glycemic Treatment: Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1):S183-S215. <a href=\"https://doi.org/10.2337/dc26-S009\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.2337/dc26-S009</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Farmacovigilancia de antidiabéticos: alertas recientes, productos falsificados y reporte al INVIMA', 'Clase 3 · Seguimiento farmacoterapéutico, farmacovigilancia y caso integrador', 5, 'video', 7, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Aplica la detección y el reporte de eventos adversos y problemas de calidad de antidiabéticos, con base en las alertas vigentes.</p><p><strong>Objetivo:</strong> Aplicar la farmacovigilancia de los antidiabéticos: reconocer señales y alertas, y reportar eventos adversos y problemas de calidad al INVIMA.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=pQOlb1_HHOo","provider":"youtube","videoId":"pQOlb1_HHOo","title":"Seguridad del Paciente en Acción: Cómo Reportar Eventos Adversos Salva Vidas en #MedSafetyWeek","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>El Programa Nacional de Farmacovigilancia del INVIMA recibe reportes de sospechas de reacciones adversas, errores de medicación y problemas de calidad, incluidos productos falsificados o sin registro. Los problemas de dispositivos (plumas, agujas, glucómetros, sensores, bombas) se reportan a tecnovigilancia.</p><p>Alertas y comunicaciones recientes que el QF debe conocer:</p><ul><li><strong>INVIMA 090-2024 (11-abr-2024):</strong> comercialización fraudulenta de \"semaglutida + B12\".</li><li><strong>INVIMA 200-2024 (2-jul-2024):</strong> falsificación de Ozempic, lotes LP6F832, MP5E511, NAR0074 y NP5G443.</li><li><strong>EMA, PRAC (abril 2024):</strong> no se encontró relación causal entre agonistas GLP-1 e ideación suicida.</li><li><strong>OMS (27-jun-2025):</strong> NAION con semaglutida, efecto muy raro (hasta 1 de cada 10.000).</li><li><strong>INVIMA 042-2025:</strong> bombas de insulina MiniMed 640G, 670G y 780G (consultar el alcance en la alerta).</li><li><strong>INVIMA 95-2026 (15-abr-2026):</strong> tirzepatida 20 mg/mL sin registro sanitario, promocionada para uso estético; el INVIMA recuerda que con tirzepatida se han reportado casos de pancreatitis aguda.</li></ul><p><strong>Cómo reportar en VigiFlow eReporting (tutorial INVIMA):</strong> se accede desde la sección de farmacovigilancia del sitio del INVIMA. Se registran las iniciales, sexo, peso y edad del paciente; la descripción del evento con fechas y gravedad; cada medicamento con nombre completo, fabricante, lote, dosis, vía, fechas e indicación, marcando el sospechoso; antecedentes relevantes; y los datos de contacto del reportante. Al enviar, el sistema genera un número de reporte. Pueden reportar pacientes, cuidadores, profesionales y establecimientos; las instituciones también reportan a través de sus programas institucionales.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una mujer de Medellín presenta vómito persistente y dolor abdominal intenso tras aplicarse una \"tirzepatida\" comprada por redes sociales. El QF la remite a urgencias, conserva el empaque y el lote, compara el producto con la alerta 95-2026 y reporta el caso en eReporting, informando dónde fue adquirido.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>Conocer las alertas vigentes permite detectar productos falsificados o sin registro.</li><li>Un buen reporte incluye lote, fechas, dosis, evolución y fuente de adquisición.</li><li>Medicamentos a farmacovigilancia; plumas, glucómetros y bombas a tecnovigilancia.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 6, '{"tone":"advertencia","title":"Nota de actualización (oct. 2026)","html":"<p>Se suma la alerta INVIMA 95-2026 sobre tirzepatida sin registro sanitario a las alertas de 2024 sobre semaglutida fraudulenta y falsificada.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
