  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 9, '{"url":"https://www.ema.europa.eu/es/news/meeting-highlights-pharmacovigilance-risk-assessment-committee-prac-8-11-april-2024","title":"Aspectos destacados de la reunión del PRAC, 8-11 de abril de 2024 (agonistas GLP-1 e ideación suicida)","description":"Página web · EMA - PRAC · 2024"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 10, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>INVIMA, Grupo de Farmacovigilancia. Reporte de problemas relacionados con medicamentos por parte de pacientes y otros actores del sistema de salud colombiano (VigiFlow eReporting): tutorial. Bogotá: INVIMA; 2025.</li><li>Instituto Nacional de Vigilancia de Medicamentos y Alimentos (INVIMA). Alerta sanitaria No. 090-2024: Semaglutida + B12. Bogotá: INVIMA; 11 abr 2024.</li><li>Instituto Nacional de Vigilancia de Medicamentos y Alimentos (INVIMA). Alerta sanitaria No. 200-2024: OZEMPIC 1,34 mg/mL (semaglutida), lotes LP6F832, MP5E511, NAR0074, NP5G443. Bogotá: INVIMA; 2 jul 2024.</li><li>Instituto Nacional de Vigilancia de Medicamentos y Alimentos (INVIMA). Alerta sanitaria No. 95-2026: Tirzepatida inyectable 20 mg/mL. Bogotá: INVIMA; 15 abr 2026.</li><li>European Medicines Agency. Meeting highlights from the Pharmacovigilance Risk Assessment Committee (PRAC) 8-11 April 2024. Amsterdam: EMA; 12 abr 2024.</li><li>Organización Mundial de la Salud. Semaglutide medicines and non-arteritic anterior ischemic optic neuropathy (NAION). Ginebra: OMS; 27 jun 2025.</li></ol>"}'::jsonb);
