  VALUES (v_curso, v_unidad, 'Caso: clasificación, riesgo y meta en una paciente con diabetes y albuminuria', 'Clase 3 · Riesgo cardiovascular y metas terapéuticas', 5, 'video', 16, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta el proceso completo de confirmación diagnóstica, estimación de riesgo y definición de meta en un caso colombiano realista.</p><p><strong>Objetivo:</strong> Ejecutar, en un caso real, la secuencia de confirmación diagnóstica, estratificación del riesgo y definición de la meta de presión arterial (PA).</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=9jo043KAFoY","provider":"youtube","videoId":"9jo043KAFoY","title":"Sociedad Europea de Cardiología GUÍA 2024 | HIPERTENSIÓN ARTERIAL","transcriptHtml":""}'::jsonb);
