  VALUES (v_clase, 'enlace', 11, '{"url":"https://www.invima.gov.co/biblioteca/preview/143859","title":"Informe Programa Demuestra la Calidad Medicamentos 2024 (2025-12)","description":"Documento · Documento oficial · autoridad sanitaria"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 12, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 13, '{"html":"<ol><li>Agencia Española de Medicamentos y Productos Sanitarios. Ficha técnica Enalapril Cinfa 5 mg, 10 mg y 20 mg comprimidos. CIMA; texto revisado jul. 2021.</li><li>McEvoy JW, McCarthy CP, Bruno RM, et al. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024;45(38):3912-4018. <a href=\"https://doi.org/10.1093/eurheartj/ehae178\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehae178</a></li><li>Instituto Nacional de Vigilancia de Medicamentos y Alimentos. Informe Programa Demuestra la Calidad Medicamentos 2024. Bogotá: INVIMA; 2025.</li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'ARA-II: losartán y otros sartanes', 'Clase 2 · Inhibidores de la ECA y antagonistas del receptor de angiotensina II', 2, 'video', 41, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Compara los ARA-II con los IECA y analiza la posología, contraindicaciones, interacciones y reacciones adversas del losartán.</p><p><strong>Objetivo:</strong> Comparar los ARA-II con los IECA y analizar el uso del losartán según su ficha técnica.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=a-B9bSYEGSs","provider":"youtube","videoId":"a-B9bSYEGSs","title":"Farmacología del Losartán y otros IECAs y  antagonistas ARA2","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Los ARA-II (losartán, valsartán, irbesartán, telmisartán, candesartán, olmesartán) bloquean el receptor AT1 de la angiotensina II. Como no aumentan la bradicinina, la tos es mucho menos frecuente que con los IECA; de hecho, la ficha técnica del losartán lo indica en insuficiencia cardiaca cuando los IECA no son adecuados por intolerancia, sobre todo por tos. Comparten con los IECA el riesgo de hiperpotasemia, deterioro de la función renal en estenosis de arteria renal y la contraindicación en el segundo y tercer trimestre del embarazo. No se deben combinar IECA con ARA-II, ni ninguno de ellos con aliskirén en diabetes o insuficiencia renal.</p><p>El losartán (ATC C09CA01) está indicado en hipertensión esencial en adultos y en niños de 6 a 18 años, en nefropatía de pacientes hipertensos con diabetes tipo 2 y proteinuria ≥0,5 g/día, en insuficiencia cardiaca crónica y en la reducción del riesgo de ictus en hipertensos con hipertrofia ventricular izquierda. La dosis habitual en HTA es 50 mg una vez al día, con efecto máximo a las 3 a 6 semanas; puede aumentarse a 100 mg. Con depleción de volumen se considera 25 mg y en mayores de 75 años puede valorarse iniciar con 25 mg. No requiere ajuste inicial en insuficiencia renal y está contraindicado en insuficiencia hepática grave. Las reacciones frecuentes en HTA son mareo, vértigo e hiperpotasemia. Interacciones relevantes: potasio y sustitutos de la sal con potasio, trimetoprim, litio y AINE.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una comerciante de 49 años de Neiva trae fórmula de losartán 50 mg tras suspender enalapril por tos. Pregunta si puede usar «sal dietética». La QF revisa la etiqueta: contiene cloruro de potasio. Le explica que, con losartán, los sustitutos de sal con potasio requieren valoración médica por riesgo de potasio alto, y la remite a su médico.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>Los ARA-II son la alternativa cuando el IECA produce tos.</li><li><strong>Losartán:</strong> 50 mg/día, hasta 100 mg; considerar 25 mg con depleción de volumen o en mayores de 75 años.</li><li>Nunca combinar IECA + ARA-II; vigilar potasio y creatinina.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 6, '{"text":"Para profundizar","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
