  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Resume el lugar de los diuréticos, los betabloqueadores y otros antihipertensivos en las guías vigentes y en el posicionamiento colombiano.</p><p><strong>Objetivo:</strong> Resumir el papel de los diuréticos, los betabloqueadores y los antihipertensivos de segunda línea dentro de la estrategia actual de tratamiento.</p>"}'::jsonb);
