  VALUES (v_clase, 'encabezado', 10, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>McEvoy JW, McCarthy CP, Bruno RM, et al. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024;45(38):3912-4018. <a href=\"https://doi.org/10.1093/eurheartj/ehae178\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehae178</a></li><li>Jones DW, Ferdinand KC, Taler SJ, et al. 2025 AHA/ACC/AANP/AAPA/ABC/ACCP/ACPM/AGS/AMA/ASPC/NMA/PCNA/SGIM guideline for the prevention, detection, evaluation and management of high blood pressure in adults. J Am Coll Cardiol. 2025. <a href=\"https://doi.org/10.1016/j.jacc.2025.05.007\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jacc.2025.05.007</a></li><li>Instituto de Evaluación Tecnológica en Salud. Informe final de posicionamiento terapéutico para el tratamiento de HTA en el marco del enfoque de APS. Bogotá: IETS-MinSalud; 2023.</li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Tiazidas y similares: hidroclorotiazida, clortalidona e indapamida', 'Clase 2 · Diuréticos en hipertensión', 1, 'video', 43, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Interpreta la ficha técnica de la hidroclorotiazida: dosis, techo terapéutico, alteraciones electrolíticas y metabólicas, y advertencias de seguridad recientes.</p><p><strong>Objetivo:</strong> Interpretar el uso de la hidroclorotiazida (HCTZ) y de los diuréticos similares a tiazidas en HTA, con énfasis en la seguridad.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=ZBboEdg399k","provider":"youtube","videoId":"ZBboEdg399k","title":"Farmacología de la hidroclorotiazida y otros diuréticos usados en la hipertensión","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>La HCTZ (ATC C03AA03) está indicada en HTA, sola o combinada, y en edemas de origen cardiaco, renal o hepático, entre otras indicaciones. En HTA se inicia con 12,5 o 25 mg una vez al día y el efecto completo aparece en 3 a 4 semanas; el intervalo útil es de 12,5 a 50 mg/día. La ficha técnica advierte que, si la respuesta es insuficiente con 25 o 50 mg/día, no se debe subir la dosis, porque no baja más la PA y aumenta la pérdida de potasio: se recomienda asociar otro antihipertensivo. Se toma por la mañana, con el desayuno. Se usa con precaución si la filtración glomerular es &lt;30 ml/min y está contraindicada en anuria.</p><p><strong>Reacciones muy frecuentes:</strong> hipopotasemia (sobre todo a dosis altas) y aumento de lípidos. Frecuentes: hiponatremia, hipomagnesemia, hiperuricemia, erupciones, náuseas, hipotensión ortostática e impotencia. Puede alterar la tolerancia a la glucosa, precipitar gota y elevar el calcio. Advertencias importantes: riesgo de cáncer de piel no melanoma dependiente de la dosis acumulada (revisar la piel y limitar la exposición solar), derrame coroideo con miopía aguda o glaucoma de ángulo cerrado (suspender), y casos muy raros de toxicidad respiratoria aguda. Interacciones: aumenta el litio; los AINE reducen su efecto y pueden causar daño renal; la hipopotasemia favorece la toxicidad por digitálicos.</p><p>La clortalidona y la indapamida son diuréticos similares a tiazidas, de acción más prolongada, y las guías los incluyen como alternativas de primera línea.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un vendedor de 57 años de Girardot, que trabaja al sol, recibe HCTZ 25 mg. La QF le explica cómo tomarla en la mañana, le recomienda protección solar y revisión de lunares o lesiones nuevas, y le indica consultar al médico si presenta calambres, debilidad o visión borrosa súbita.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li><strong>HCTZ:</strong> 12,5 a 25 mg/día en la mañana; si no hay respuesta, se asocia otro fármaco en lugar de subir la dosis.</li><li>Vigilar potasio, sodio, ácido úrico y glucosa.</li><li>Educar sobre cuidado de la piel y síntomas visuales de alarma.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 6, '{"tone":"advertencia","title":"Nota de actualización (oct. 2026)","html":"<p>La ficha técnica consultada se revisó en diciembre de 2025 e incluye las advertencias de cáncer de piel no melanoma, derrame coroideo y toxicidad respiratoria aguda.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
