  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 4. Estrategia terapéutica, HTA resistente y poblaciones especiales', 3)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Introducción a la unidad: algoritmos de tratamiento y protocolos estandarizados', 'Clase 1 · Introducción a la unidad', 0, 'video', 17, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Resume el algoritmo de tratamiento de las guías vigentes y los protocolos estandarizados HEARTS de la OPS, incluida la vía clínica HEARTS 2.0.</p><p><strong>Objetivo:</strong> Resumir el algoritmo de tratamiento farmacológico de la HTA y el valor de los protocolos estandarizados en la atención primaria.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=aeFhUKG6Ng4","provider":"youtube","videoId":"aeFhUKG6Ng4","title":"Domina la Hipertensión Arterial en 2025 con las Nuevas Guías Europeas en Solo 10 Minutos / ESC","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>La guía ESC 2024 propone, para la mayoría de los pacientes con HTA confirmada, iniciar con una combinación de dos fármacos a dosis bajas: un IECA o ARA-II más un calcioantagonista dihidropiridínico o un diurético tipo tiazida, de preferencia en una sola tableta. Si no se alcanza la meta, se pasa a la triple combinación (IECA o ARA-II + calcioantagonista + diurético) y, si persiste la PA alta, se considera la HTA resistente y se añade espironolactona u otra alternativa. La monoterapia inicial puede considerarse en PA elevada con riesgo alto, en personas de 85 años o más, con fragilidad moderada o grave o con hipotensión ortostática sintomática. La guía AHA/ACC 2025, por su parte, recomienda iniciar con dos fármacos de primera línea de clases distintas en el estadio 2, preferiblemente en una sola tableta.</p><p>La iniciativa HEARTS de la OPS impulsa protocolos estandarizados con pocos medicamentos, dosis y pasos definidos, combinaciones en una sola tableta y trabajo en equipo, incluidos los servicios farmacéuticos. Según la OPS, la primera versión de su vía clínica fue adoptada como estándar nacional de HTA en 29 países de las Américas. En mayo de 2026 se lanzó HEARTS 2.0, que mantiene el control de la PA como puerta de entrada y amplía las recomendaciones a la prevención cardio-renal-metabólica, con listas de medicamentos esenciales y pautas de seguimiento.</p><p>Esta unidad aborda las combinaciones en dosis fija, la HTA resistente, las poblaciones especiales (enfermedad renal crónica, diabetes, embarazo y adulto mayor) y las crisis hipertensivas.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Una IPS de primer nivel en Sincelejo adopta un protocolo estandarizado de HTA. La QF participa en la selección de las presentaciones disponibles, en la definición de la secuencia de pasos y en el diseño del registro de dispensación para identificar a quienes no avanzan en el protocolo pese a no estar en meta.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>La mayoría de los pacientes inicia con dos fármacos a dosis bajas, preferiblemente en una sola tableta.</li><li>Los protocolos estandarizados simplifican la prescripción y mejoran el control poblacional.</li><li>HEARTS 2.0 (2026) integra la prevención cardio-renal-metabólica.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 6, '{"tone":"advertencia","title":"Nota de actualización (oct. 2026)","html":"<p>La OPS lanzó la vía clínica HEARTS 2.0 el 15 de mayo de 2026.</p>"}'::jsonb);
