  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>Jones DW, Ferdinand KC, Taler SJ, et al. 2025 AHA/ACC/AANP/AAPA/ABC/ACCP/ACPM/AGS/AMA/ASPC/NMA/PCNA/SGIM guideline for the prevention, detection, evaluation and management of high blood pressure in adults. J Am Coll Cardiol. 2025. <a href=\"https://doi.org/10.1016/j.jacc.2025.05.007\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jacc.2025.05.007</a></li><li>McEvoy JW, McCarthy CP, Bruno RM, et al. 2024 ESC Guidelines for the management of elevated blood pressure and hypertension. Eur Heart J. 2024;45(38):3912-4018. <a href=\"https://doi.org/10.1093/eurheartj/ehae178\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehae178</a></li><li>Koga M, et al. Blood pressure management in stroke: comparative review of the 2025 AHA/ACC/AANP/ACPM/AGS/AMA/ASPC/NMA/PCNA/SGIM, 2024 ESC, 2023 ESH, and 2025 JSH guidelines. Hypertens Res. 2026;49:984-7. <a href=\"https://doi.org/10.1038/s41440-025-02517-0\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1038/s41440-025-02517-0</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Caso: HTA aparentemente resistente en un paciente con diabetes y enfermedad renal crónica', 'Clase 4 · Situaciones agudas y caso de la unidad', 7, 'video', 77, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta la evaluación farmacoterapéutica de una HTA aparentemente resistente, integrando adherencia, interacciones, población especial y comunicación con el médico.</p><p><strong>Objetivo:</strong> Ejecutar la evaluación farmacoterapéutica de una HTA aparentemente resistente en un paciente con diabetes y enfermedad renal crónica (ERC).</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=ZBB017kEr-Q","provider":"youtube","videoId":"ZBB017kEr-Q","title":"Guía ESC 2024 sobre el manejo de la HTA","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p><strong>Caso:</strong> Álvaro, 63 años, de Cúcuta, con diabetes tipo 2 y ERC (TFGe 52 ml/min/1,73 m²; relación albúmina/creatinina 180 mg/g). Recibe losartán 100 mg, amlodipino 10 mg e hidroclorotiazida 25 mg, además de metformina. PA en consultorio 156/92 mmHg; AMPA 148/88 mmHg. Potasio 4,6 mmol/l. Toma naproxeno por dolor lumbar casi a diario, ronca y tiene somnolencia diurna. Los registros muestran que retira sus medicamentos cada 40 a 45 días.</p><p><strong>Análisis por pasos:</strong> 1) La AMPA confirma PA fuera de meta, no es bata blanca. 2) Adherencia: los retiros sugieren una cobertura cercana al 70 %; antes de hablar de resistencia hay que mejorarla. 3) Interferencias: el naproxeno puede elevar la PA, reducir el efecto del losartán y la tiazida y, junto con ellos, deteriorar la función renal y elevar el potasio. 4) Causas secundarias: el ronquido y la somnolencia orientan a posible apnea del sueño; corresponde al médico evaluar también el hiperaldosteronismo primario. 5) Si tras corregir lo anterior la PA sigue alta, la guía ESC 2024 propone añadir espironolactona con vigilancia estrecha de potasio y creatinina, especialmente con TFGe reducida. 6) Por su diabetes con albuminuria, el médico puede valorar terapias cardiorrenales adicionales.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p><strong>La QF elabora un plan de seguimiento:</strong> entrevista sobre barreras de adherencia (costo del transporte y olvidos), propuesta de pastillero y recordatorios, nota al médico con los hallazgos (adherencia, naproxeno, síntomas de apnea) y solicitud de valorar analgesia alternativa. Acuerda con el paciente AMPA por 7 días y nuevo encuentro en un mes con potasio y creatinina.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li><strong>Antes de declarar resistencia:</strong> confirmar con AMPA, medir adherencia y retirar interferencias.</li><li>Los AINE son una causa frecuente y evitable de mal control y daño renal.</li><li>El cuarto fármaco se añade con vigilancia de potasio y función renal, por decisión médica.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 6, '{"text":"Para profundizar","level":2}'::jsonb);
