  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=CAL4aCsUgmg","provider":"youtube","videoId":"CAL4aCsUgmg","title":"Adherencia y reconciliación de medicamentos","transcriptHtml":""}'::jsonb);
