  VALUES (v_clase, 'enlace', 10, '{"url":"https://www.invima.gov.co/invima_website/static/attachments/medicamentos_vigilancia_sqb/1._gu_C3_ADa_para_la_implementaci_C3_B3n_-_gesti_C3_B3n_de_alertas_sanitarias_-_versi_C3_B3n_2__2_.pdf","title":"Guía para la implementación – gestión de alertas sanitarias (versión 2.0, 15/03/2025) (2025-03-15)","description":"Documento · Documento oficial · autoridad sanitaria"}'::jsonb);
