  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 8, '{"url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/INEC/IETS/informe-posicionamiento-terapeutico-tratamiento-hta-enfoque-aps.pdf","title":"Informe final de posicionamiento terapéutico para el tratamiento de HTA en el marco del enfoque de APS","description":"PDF · IETS / Ministerio de Salud y Protección Social (Colombia) · 2023 · versión vigente"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
