  VALUES (v_curso, v_unidad, 'Ficha: Losartán potásico', 'Anexo · Fichas de medicamentos', 0, 'manual', 10, FALSE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"Cómo leer esta ficha","html":"<p>Resumen de la ficha técnica de referencia: Ficha técnica Losartán Cinfa 50 mg comprimidos recubiertos con película EFG (AEMPS-CIMA) (2025-02). En Colombia prevalece el inserto aprobado por el INVIMA para cada registro sanitario: verifica siempre el del producto que dispensas.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 1, '{"html":"<h3>Grupo farmacológico</h3><p>Antagonistas de la angiotensina II (ARA-II) solos — ATC C09CA01</p><h3>Marcas de referencia</h3><p>Se comercializa ampliamente como genérico; también en combinación con hidroclorotiazida. Marca original de referencia internacional: Cozaar® (referencia informativa; verificar registro vigente en INVIMA).</p><h3>Indicaciones</h3><p>Hipertensión esencial en adultos y en niños y adolescentes de 6 a 18 años; enfermedad renal en adultos con hipertensión y diabetes tipo 2 con proteinuria ≥0,5 g/día; insuficiencia cardiaca crónica en adultos cuando los IECA no son adecuados (intolerancia, sobre todo tos, o contraindicación); reducción del riesgo de ictus en hipertensos con hipertrofia ventricular izquierda documentada por ECG.</p><h3>Posología</h3><p><strong>HTA en adultos:</strong> 50 mg una vez al día; efecto máximo a las 3–6 semanas; puede aumentarse a 100 mg una vez al día. Depleción de volumen intravascular: considerar 25 mg/día. Mayores de 75 años: valorar inicio con 25 mg. Insuficiencia renal o hemodiálisis: sin ajuste de la dosis inicial. Insuficiencia hepática: considerar dosis menor (contraindicado si es grave). Niños de 6 a 18 años: &gt;20 a &lt;50 kg, 25 mg/día (excepcionalmente hasta 50 mg); &gt;50 kg, 50 mg/día (excepcionalmente hasta 100 mg). No se recomienda en menores de 6 años.</p><h3>Administración</h3><p>Vía oral. Tragar los comprimidos enteros con un vaso de agua, con o sin alimentos.</p><h3>Contraindicaciones</h3><p>Hipersensibilidad al principio activo o a los excipientes; segundo y tercer trimestre del embarazo; insuficiencia hepática grave; uso concomitante con aliskirén en pacientes con diabetes mellitus o insuficiencia renal (TFG &lt;60 ml/min/1,73 m²).</p><h3>Advertencias y precauciones</h3><p>Angioedema (vigilar a pacientes con antecedentes); hipotensión sintomática con depleción de volumen o sodio; hiperpotasemia (controlar potasio y función renal; evitar suplementos de potasio, ahorradores de potasio y sustitutos de sal con potasio); estenosis bilateral de arteria renal o de riñón único; hiperaldosteronismo primario (no recomendado); bloqueo dual del SRAA no recomendado (no combinar con IECA o aliskirén; no combinar IECA y ARA-II en nefropatía diabética).</p><h3>Embarazo y lactancia</h3><p>No iniciar durante el embarazo; no recomendado en el primer trimestre y contraindicado en el segundo y tercero; si se confirma embarazo, suspender de inmediato e iniciar alternativa. Lactancia: no recomendado por falta de información; preferir alternativas con perfil de seguridad establecido.</p><h3>Reacciones adversas muy frecuentes</h3><p>No se describen reacciones muy frecuentes en la tabla de la ficha técnica; la más frecuente en ensayos fue el mareo.</p><h3>Reacciones adversas frecuentes</h3><p><strong>En hipertensión:</strong> mareo, vértigo, hiperpotasemia. En otras indicaciones: astenia, fatiga, hipotensión ortostática, anemia, alteración o fallo renal, aumento de urea, creatinina y potasio, hipoglucemia (en hipertensión con diabetes tipo 2 y enfermedad renal).</p><h3>Interacciones</h3><p>Suplementos de potasio, diuréticos ahorradores de potasio, sustitutos de sal con potasio, heparina y medicamentos con trimetoprim (hiperpotasemia); litio (aumento de concentraciones y toxicidad); AINE, incluidos inhibidores de COX-2 y ácido acetilsalicílico a dosis antiinflamatorias (menor efecto antihipertensivo, deterioro renal e hiperpotasemia); aliskirén e IECA (bloqueo dual: hipotensión, hiperpotasemia, disfunción renal).</p><h3>Conservación</h3><p>No requiere condiciones especiales de conservación. Conservar en el envase original.</p><h3>Alertas del INVIMA</h3><p>Alerta Sanitaria No. 243-2021: retiro voluntario de todos los lotes de dos productos de losartán potásico 50 mg y 100 mg (registros 2009M-0010223 y 2009M-0010212) por impureza de tipo azido; recomendación de no suspender el tratamiento sin consultar al médico. https://www.invima.gov.co/biblioteca/alerta-sanitaria-losartan-retiro-impureza-azido-243-2021</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 2, '{"tone":"consejo","title":"Cómo explicárselo al paciente","html":"<p>El losartán es un medicamento para la presión alta que relaja los vasos sanguíneos. También protege el riñón en algunas personas con diabetes y se usa en ciertos casos de insuficiencia cardiaca. Se usa solo con fórmula médica. Por lo general se toma una vez al día, con o sin comida; su médico le indicará la dosis. El efecto completo tarda de 3 a 6 semanas. Tómelo todos los días aunque se sienta bien y no lo suspenda sin consultar. Puede producir mareo, sobre todo al principio, y subir el potasio en la sangre; por eso su médico le pedirá exámenes. No use sal con potasio, suplementos de potasio ni antiinflamatorios sin consultar. No debe usarse en el embarazo: si planea uno, hable antes con su médico. Si se le hinchan la cara, los labios o la garganta, o le cuesta respirar, vaya a urgencias.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 3, '{"url":"https://cima.aemps.es/cima/dochtml/ft/67729/FT_67729.html","title":"Ficha técnica: Ficha técnica Losartán Cinfa 50 mg comprimidos recubiertos con película EFG (AEMPS-CIMA)","description":"Fuente oficial · 2025-02"}'::jsonb);
