  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 11, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 12, '{"html":"<ol><li>Køber L, Adamo M, Ruwald AC, et al. 2026 ESC Guidelines for the management of heart failure. Eur Heart J. 2026;47(38):5346. <a href=\"https://doi.org/10.1093/eurheartj/ehag100\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehag100</a></li><li>Maddox TM, Januzzi JL Jr, Allen LA, et al. 2024 ACC Expert Consensus Decision Pathway for Treatment of Heart Failure With Reduced Ejection Fraction. J Am Coll Cardiol. 2024. <a href=\"https://doi.org/10.1016/j.jacc.2023.12.024\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jacc.2023.12.024</a></li><li>McDonagh TA, Metra M, Adamo M, et al. 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2021;42(36):3599-726. <a href=\"https://doi.org/10.1093/eurheartj/ehab368\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehab368</a></li><li>How to optimize goal-directed medical therapy (GDMT) in patients with heart failure. Curr Cardiol Rep. 2024. <a href=\"https://doi.org/10.1007/s11886-024-02101-x\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1007/s11886-024-02101-x</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'ARNI: sacubitrilo/valsartán — mecanismo, inicio, titulación y transición desde IECA', 'Clase 2 · Bloqueo del sistema renina-angiotensina y de la neprilisina', 1, 'video', 18, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Interpreta el mecanismo, la posología, la transición desde IECA (36 h), los ajustes y las precauciones de sacubitrilo/valsartán según la ficha técnica.</p><p><strong>Objetivo:</strong> Interpretar el uso de sacubitrilo/valsartán en la IC con FEVI reducida según su ficha técnica.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=JgiUpWSFTPY","provider":"youtube","videoId":"JgiUpWSFTPY","title":"SACUBITRILO/VALSARTÁN - EN EL TRATAMIENTO DE INSUFICIENCIA CARDÍACA","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Sacubitrilo/valsartán combina un inhibidor de la neprilisina (sacubitrilo), que aumenta los péptidos natriuréticos, con un ARA-II (valsartán), que bloquea los efectos de la angiotensina II. Su ficha técnica lo indica en adultos con IC crónica sintomática con fracción de eyección reducida y en niños desde un año con IC sintomática y disfunción sistólica.</p><p><strong>Posología en adultos:</strong> se inicia con 49/51 mg cada 12 horas y se duplica a las 2-4 semanas hasta la dosis objetivo de 97/103 mg cada 12 horas, según tolerancia. Se usa la dosis de 24/26 mg cada 12 horas, con aumentos cada 3-4 semanas, en quienes no tomaban IECA o ARA-II o los tomaban a dosis bajas, y se considera con presión sistólica de 100-110 mmHg. No se debe iniciar con potasio &gt;5,4 mmol/L ni con presión sistólica &lt;100 mmHg.</p><p><strong>Transición desde IECA:</strong> está contraindicado darlo junto con un IECA y hasta 36 horas después de la última dosis del IECA, por el riesgo de angioedema. Tampoco se combina con otro ARA-II.</p><p><strong>Ajustes:</strong> con TFG de 30-60 mL/min/1,73 m² se considera la mitad de la dosis inicial; con TFG &lt;30 la experiencia es muy limitada y se usa con precaución y a mitad de dosis; en enfermedad renal terminal no se recomienda. En insuficiencia hepática moderada se usa la mitad de la dosis inicial; en la grave, la cirrosis biliar y la colestasis está contraindicado.</p><p><strong>Precauciones:</strong> hipotensión (mayor riesgo en ≥65 años, enfermedad renal y presión sistólica &lt;112 mmHg), hiperpotasemia, deterioro renal (sobre todo con deshidratación o AINE) y angioedema, que obliga a suspenderlo para siempre. Está contraindicado con antecedente de angioedema y en el segundo y tercer trimestre del embarazo. Las reacciones muy frecuentes son hiperpotasemia, hipotensión e insuficiencia renal.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un paciente de Manizales toma enalapril 10 mg cada 12 horas; su última dosis fue el lunes a las 8 p. m. El cardiólogo formula sacubitrilo/valsartán. El QF le explica que no debe tomarlo antes del miércoles a las 8 a. m. y que no debe volver a tomar enalapril.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>Inicio habitual 49/51 mg cada 12 h; objetivo 97/103 mg cada 12 h.</li><li>Se requieren 36 horas sin IECA antes de la primera dosis.</li><li>Vigilar presión arterial, potasio, creatinina y signos de angioedema.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
