  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 11, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 12, '{"html":"<ol><li>Maddox TM, Januzzi JL Jr, Allen LA, et al. 2024 ACC Expert Consensus Decision Pathway for Treatment of Heart Failure With Reduced Ejection Fraction. J Am Coll Cardiol. 2024. <a href=\"https://doi.org/10.1016/j.jacc.2023.12.024\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jacc.2023.12.024</a></li><li>AEMPS. Ficha técnica Entresto 24 mg/26 mg, 49 mg/51 mg y 97 mg/103 mg comprimidos recubiertos con película. CIMA [consultado 27 oct 2026].</li><li>AEMPS. Ficha técnica Espironolactona Accord 25 mg comprimidos recubiertos con película EFG. CIMA; revisión abril 2025 [consultado 27 oct 2026].</li><li>Køber L, Adamo M, Ruwald AC, et al. 2026 ESC Guidelines for the management of heart failure. Eur Heart J. 2026;47(38):5346. <a href=\"https://doi.org/10.1093/eurheartj/ehag100\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehag100</a></li></ol>"}'::jsonb);

  INSERT INTO aula_modules (course_id, title, sort_order)
  VALUES (v_curso, 'Unidad 3. Implementación segura: titulación, diuréticos, potasio y función renal', 2)
  RETURNING id INTO v_unidad;
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Introducción a la unidad: de la fórmula a la dosis óptima, implementación segura de la terapia fundamental', 'Clase 1 · Introducción a la unidad', 0, 'video', 23, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Resume por qué la terapia fundamental suele quedar incompleta y qué estrategias de inicio rápido, titulación y vigilancia recomiendan las guías.</p><p><strong>Objetivo:</strong> Resumir los retos de la implementación de la terapia fundamental y las estrategias que proponen las guías para superarlos.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=pCTwkXP9Q3c","provider":"youtube","videoId":"pCTwkXP9Q3c","title":"TEMA 15 OPTIMIZACIÓN TERAPÉUTICA EN LA ICFEr: DE LA EVIDENCIA A LA PRÁCTICA CLÍNICA","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Conocer los cuatro pilares no basta. En la práctica muchos pacientes reciben solo algunos de ellos o dosis bajas que nunca se ajustan; estudios recientes, incluidos análisis de hospitales comunitarios, describen ese uso incompleto. Las razones más comunes son el temor a la hipotensión, a la hiperpotasemia o al aumento de la creatinina, la inercia clínica, las visitas poco frecuentes y las barreras de acceso.</p><p>La actualización de 2023 de la guía ESC incorporó, con base en el ensayo STRONG-HF, una estrategia intensiva: iniciar y subir rápido los tratamientos antes del alta y en visitas frecuentes durante las 6 semanas siguientes, con control de síntomas, presión arterial, frecuencia cardíaca, potasio, creatinina y NT-proBNP. Análisis posteriores, como el de 2025 por etiología, siguen estudiando qué pacientes se benefician. La Guía ESC 2026, según los resúmenes publicados, insiste en optimizar rápido, con aumentos cada 1-2 semanas cuando sea posible, y en no suspender el tratamiento cuando el paciente mejora.</p><p><strong>Esta unidad aborda cuatro temas:</strong> 1) cómo secuenciar y titular; 2) qué hacer ante hipotensión o bradicardia; 3) cómo usar los diuréticos de asa y manejar la resistencia diurética; y 4) cómo interpretar el potasio y la función renal sin suspender innecesariamente medicamentos que salvan vidas.</p><p>Para el QF, la titulación es un proceso que se puede protocolizar: una lista de chequeo antes de cada cambio, un calendario de laboratorios y una comunicación clara con el médico y con el paciente.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>En un programa de falla cardíaca de Bucaramanga, el QF diseña un calendario: visita o teleconsulta cada 2 semanas durante 3 meses, con presión, frecuencia, peso, potasio y creatinina. En cada visita propone al médico un solo ajuste y deja registrada la razón cuando no se puede subir una dosis.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>La terapia incompleta y las dosis bajas son el principal problema de implementación.</li><li>Iniciar antes del alta y titular en visitas frecuentes es la estrategia recomendada.</li><li>Un protocolo con lista de chequeo y laboratorios hace la titulación segura.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 6, '{"text":"Para profundizar","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 7, '{"url":"https://www.jacc.org/doi/10.1016/j.jchf.2024.08.004","title":"Inpatient Use of Guideline-Directed Medical Therapy During Heart Failure Hospitalizations Among Community-Based Health Systems","description":"Página web · JACC: Heart Failure (en inglés) · 2024"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 8, '{"url":"https://doi.org/10.1016/j.jchf.2025.102615","title":"Rapid titration of heart failure therapies by etiology: an analysis of STRONG-HF. JACC Heart Fail. 2025.","description":"Artículo científico · DOI 10.1016/j.jchf.2025.102615"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 9, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 10, '{"html":"<ol><li>McDonagh TA, Metra M, Adamo M, et al. 2023 Focused Update of the 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2023;44(37):3627-39. <a href=\"https://doi.org/10.1093/eurheartj/ehad195\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehad195</a></li><li>Køber L, Adamo M, Ruwald AC, et al. 2026 ESC Guidelines for the management of heart failure. Eur Heart J. 2026;47(38):5346. <a href=\"https://doi.org/10.1093/eurheartj/ehag100\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehag100</a></li><li>Rapid titration of heart failure therapies by etiology: an analysis of STRONG-HF. JACC Heart Fail. 2025. <a href=\"https://doi.org/10.1016/j.jchf.2025.102615\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jchf.2025.102615</a></li><li>Maddox TM, Januzzi JL Jr, Allen LA, et al. 2024 ACC Expert Consensus Decision Pathway for Treatment of Heart Failure With Reduced Ejection Fraction. J Am Coll Cardiol. 2024. <a href=\"https://doi.org/10.1016/j.jacc.2023.12.024\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jacc.2023.12.024</a></li></ol>"}'::jsonb);
