  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta un esquema de inicio y titulación de los cuatro pilares, priorizando según presión, frecuencia cardíaca, potasio, función renal y congestión.</p><p><strong>Objetivo:</strong> Ejecutar un esquema ordenado de inicio y titulación de la terapia fundamental.</p>"}'::jsonb);
