  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 10, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>Maddox TM, Januzzi JL Jr, Allen LA, et al. 2024 ACC Expert Consensus Decision Pathway for Treatment of Heart Failure With Reduced Ejection Fraction. J Am Coll Cardiol. 2024. <a href=\"https://doi.org/10.1016/j.jacc.2023.12.024\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jacc.2023.12.024</a></li><li>Køber L, Adamo M, Ruwald AC, et al. 2026 ESC Guidelines for the management of heart failure. Eur Heart J. 2026;47(38):5346. <a href=\"https://doi.org/10.1093/eurheartj/ehag100\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehag100</a></li><li>McDonagh TA, Metra M, Adamo M, et al. 2023 Focused Update of the 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2023;44(37):3627-39. <a href=\"https://doi.org/10.1093/eurheartj/ehad195\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehad195</a></li><li>Rapid uptitration of guideline-directed medical therapies in acute heart failure with and without atrial fibrillation. JACC Heart Fail. 2024. <a href=\"https://doi.org/10.1016/j.jchf.2024.06.010\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jchf.2024.06.010</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Hipotensión, bradicardia, fatiga y otras barreras de la titulación: qué ajustar primero', 'Clase 2 · Inicio y titulación de la terapia fundamental', 2, 'video', 87, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Aplica criterios para manejar hipotensión, bradicardia y empeoramiento transitorio durante la titulación sin abandonar la terapia fundamental.</p><p><strong>Objetivo:</strong> Aplicar criterios prácticos para manejar las barreras más frecuentes de la titulación sin abandonar la terapia que modifica el pronóstico.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=x2lOeFIr8ps","provider":"youtube","videoId":"x2lOeFIr8ps","title":"Insuficiencia cardíaca en el adulto mayor cómo optimizar el tratamiento: Fragilidad y polifarmacia","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Hipotensión. Muchos pacientes con FEVIr tienen presión sistólica entre 95 y 110 mmHg; si no hay síntomas, esto no suele obligar a cambiar el tratamiento, según las recomendaciones prácticas de la guía ESC 2021. Si hay mareo o síncope, el orden sugerido es: 1) retirar fármacos que bajan la presión y no aportan pronóstico (nitratos sin angina, calcioantagonistas, alfabloqueadores como tamsulosina o doxazosina); 2) si no hay congestión, reducir el diurético; 3) solo después, reducir temporalmente la dosis del ARNI, IECA o ARA-II. La ficha técnica de sacubitrilo/valsartán indica ajustar la medicación concomitante, reducir temporalmente o interrumpir ante presión sistólica ≤95 mmHg o hipotensión sintomática. Un análisis de STRONG-HF de 2024 estudió la relación entre presión arterial y la titulación intensiva.</p><p>Bradicardia. La ficha técnica del carvedilol indica reducir la dosis si la frecuencia baja de 55 lpm. Antes, revisar otros fármacos que la bajan: digoxina, amiodarona, verapamilo, diltiazem e ivabradina. La bradicardia asintomática por encima de ese umbral no obliga a reducir.</p><p>Fatiga y retención de líquidos con betabloqueador. Son frecuentes al subir la dosis. La ficha técnica del carvedilol señala que el empeoramiento de la IC durante la titulación puede requerir aumentar el diurético, reducir la dosis o suspender temporalmente; no se debe suspender de forma brusca.</p><p>Paciente frágil o anciano. Titular más despacio, vigilar ortostatismo y caídas, revisar polifarmacia y asegurar un cuidador que conozca el plan.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>En Armenia, un hombre de 76 años con FEVIr refiere mareo al levantarse; presión de 96/60 mmHg sentado. Toma ARNI 49/51 mg cada 12 h, carvedilol 12,5 mg cada 12 h, espironolactona, dapagliflozina, furosemida 40 mg y tamsulosina 0,4 mg. No tiene edemas. El QF propone al médico revisar la tamsulosina con urología y reducir la furosemida a 20 mg, manteniendo los cuatro pilares, y controlar presión en una semana.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>Presión baja sin síntomas no obliga a reducir la terapia fundamental.</li><li>Ante hipotensión sintomática, primero retirar fármacos no esenciales y ajustar el diurético.</li><li>Con carvedilol, reducir la dosis si la frecuencia cae por debajo de 55 lpm; nunca suspender bruscamente.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
