  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 9, '{"url":"https://doi.org/10.1016/j.jchf.2025.102514","title":"MRAs, SGLT2 inhibitors, and kidney outcomes in CKD and HF: differences in diseases, drugs, or both? JACC Heart Fail. 2025.","description":"Artículo científico · DOI 10.1016/j.jchf.2025.102514"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 10, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>McDonagh TA, Metra M, Adamo M, et al. 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2021;42(36):3599-726. <a href=\"https://doi.org/10.1093/eurheartj/ehab368\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehab368</a></li><li>Biegus J, et al. Congestion, decongestion, renal function and diuretics in (ESC) heart failure. ESC Heart Fail. 2024. <a href=\"https://doi.org/10.1002/ehf2.15164\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1002/ehf2.15164</a></li><li>Agencia Europea de Medicamentos. Forxiga (dapagliflozina): ficha técnica o resumen de las características del producto [consultado 27 oct 2026].</li><li>MRAs, SGLT2 inhibitors, and kidney outcomes in CKD and HF: differences in diseases, drugs, or both? JACC Heart Fail. 2025. <a href=\"https://doi.org/10.1016/j.jchf.2025.102514\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jchf.2025.102514</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Caso: hiperpotasemia y creatinina en ascenso en un paciente con FEVI reducida en Cali', 'Clase 4 · Potasio y función renal', 7, 'video', 21, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta el análisis de un evento de hiperpotasemia por interacción, propone ajustes al médico y gestiona el reporte de farmacovigilancia.</p><p><strong>Objetivo:</strong> Ejecutar el abordaje farmacoterapéutico de una hiperpotasemia con deterioro renal y documentarla como evento adverso.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=fnGEqquaBwo","provider":"youtube","videoId":"fnGEqquaBwo","title":"Case-Based Approach: Managing Hyperkalemia in Patients With CKD and Heart Failure","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Caso. Hombre de 70 años, de Cali, con FEVIr de 25 % y enfermedad renal crónica (creatinina basal 1,6 mg/dL). Toma sacubitrilo/valsartán 49/51 mg cada 12 h, espironolactona 25 mg, carvedilol 12,5 mg cada 12 h, dapagliflozina 10 mg y furosemida 40 mg. Hace 5 días inició diclofenaco 50 mg cada 8 h por dolor lumbar, por recomendación de un vecino, y usa un sustituto de sal con potasio. Hoy: potasio 5,8 mmol/L, creatinina 2,1 mg/dL, presión 104/64 mmHg, sin edemas, con poca ingesta de líquidos.</p><p>Paso 1, gravedad. Confirmar el potasio y pedir electrocardiograma. Si hay cambios en el ECG o el potasio es muy alto, se requiere atención urgente.</p><p>Paso 2, causas. Diclofenaco (AINE: reduce el flujo renal y la respuesta al diurético), sustituto de sal con potasio, deshidratación con diurético, y la combinación ARNI + ARM.</p><p>Paso 3, propuesta al médico. Suspender el diclofenaco y el sustituto de sal. Con potasio mayor de 5 mEq/L, la ficha técnica de espironolactona indica suspender o interrumpir; con potasio mayor de 5,4 mmol/L, la de sacubitrilo/valsartán indica considerar interrumpir. Revisar la volemia y valorar reducir temporalmente la furosemida. Repetir potasio y creatinina en 48-72 horas. Cuando se normalicen, planear la reintroducción gradual; si la hiperpotasemia recurre, considerar un quelante de potasio para sostener la terapia fundamental.</p><p>Paso 4, analgesia segura. Sugerir al médico una alternativa sin AINE y educar al paciente sobre automedicación.</p><p>Paso 5, farmacovigilancia. La hiperpotasemia con deterioro renal asociada a la interacción es un evento adverso que debe notificarse. Según la Resolución INVIMA 2024015321 de 2024, profesionales y pacientes reportan en la plataforma eReporting.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p><strong>El QF registra:</strong> \"Evento: hiperpotasemia 5,8 mmol/L y lesión renal aguda. Fármacos sospechosos: diclofenaco, espironolactona, sacubitrilo/valsartán; factor contribuyente: sustituto de sal con potasio. Evolución: K 4,9 mmol/L y creatinina 1,7 mg/dL a las 72 h\". Luego hace el reporte.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>Un AINE y un sustituto de sal pueden desencadenar hiperpotasemia grave.</li><li>Ajustar según los umbrales de cada ficha técnica y planear la reintroducción.</li><li>Reportar el evento al Programa Nacional de Farmacovigilancia.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 6, '{"text":"Para profundizar","level":2}'::jsonb);
