  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 10, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>McDonagh TA, Metra M, Adamo M, et al. 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2021;42(36):3599-726. <a href=\"https://doi.org/10.1093/eurheartj/ehab368\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehab368</a></li><li>Køber L, Adamo M, Ruwald AC, et al. 2026 ESC Guidelines for the management of heart failure. Eur Heart J. 2026;47(38):5346. <a href=\"https://doi.org/10.1093/eurheartj/ehag100\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehag100</a></li><li>American College of Cardiology Solution Set Oversight Committee. 2024 ACC Expert Consensus Decision Pathway on Clinical Assessment, Management, and Trajectory of Patients Hospitalized With Heart Failure Focused Update. J Am Coll Cardiol. 2024. <a href=\"https://doi.org/10.1016/j.jacc.2024.06.002\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jacc.2024.06.002</a></li><li>Mocan D, et al. Pulmonary congestion relief by adding dapagliflozin to intravenous loop diuretic in acute heart failure patients. ESC Heart Fail. 2025. <a href=\"https://doi.org/10.1002/ehf2.15356\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1002/ehf2.15356</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Transición al alta: optimización de la terapia fundamental, iSGLT2 intrahospitalario y seguimiento temprano', 'Clase 2 · IC descompensada y transición al alta', 2, 'video', 17, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta una lista de verificación para el alta segura del paciente con IC: terapia fundamental, plan diurético, educación, controles y cita temprana.</p><p><strong>Objetivo:</strong> Ejecutar una transición al alta segura que reduzca el riesgo de reingreso del paciente con IC.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=YqFM7nwdCBY","provider":"youtube","videoId":"YqFM7nwdCBY","title":"Inicio de medicación en pacientes con FEVI reducida. En búsqueda del nuevo algoritmo. Dra. Soler","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Las semanas que siguen a una hospitalización por IC son de alto riesgo de reingreso y muerte. La hospitalización es también la mejor oportunidad para iniciar o completar la terapia fundamental: el paciente está monitorizado, se pueden controlar presión, potasio y creatinina, y se puede educar al paciente y a su familia. Análisis de 2024 sobre sistemas de salud comunitarios describen que esta oportunidad a menudo se desaprovecha.</p><p>Recomendaciones clave:</p><ul><li><strong>Actualización ESC 2023 (basada en STRONG-HF):</strong> iniciar y titular de forma intensiva antes del alta y en visitas frecuentes durante las 6 semanas siguientes.</li><li><strong>Guía ESC 2026 (según los resúmenes publicados):</strong> iniciar el iSGLT2 en el hospital una vez estabilizado el paciente y optimizar rápido antes y después del alta.</li><li><strong>Guía ESC 2021:</strong> control temprano, en 1-2 semanas tras el alta.</li></ul><p>Lista de verificación del QF antes del alta:</p><ol><li>Paciente euvolémico o casi, con peso de alta registrado.</li><li>Los cuatro pilares iniciados en FEVIr, salvo contraindicación documentada, con la dosis y el plan de titulación escritos.</li><li>Plan diurético claro, con instrucciones de autoajuste por peso si aplica.</li><li><strong>Conciliación:</strong> suspender duplicidades, AINE y fármacos que empeoran la IC; revisar interacciones.</li><li>Laboratorio de control (potasio y creatinina) en 1-2 semanas.</li><li>Cita médica temprana y contacto con el programa de IC.</li><li><strong>Educación con método de \"enseñar y repetir\":</strong> signos de alarma, peso diario, sal, adherencia.</li><li>Verificar que la EPS dispense todos los medicamentos sin interrupción.</li></ol><p>En Colombia hay estudios sobre la adherencia a las guías en el manejo hospitalario de la IC descompensada que ayudan a identificar brechas locales.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>En una clínica de Medellín, un paciente con FEVIr va a salir tras 5 días de hospitalización. Recibe furosemida oral, ARNI 24/26 mg cada 12 h y carvedilol 3,125 mg cada 12 h. El QF nota que faltan iSGLT2 y ARM; el potasio es de 4,3 mmol/L y la TFG de 60. Propone iniciar dapagliflozina antes del alta y programar la espironolactona en el primer control, con laboratorio a la semana.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>La hospitalización es una oportunidad para completar la terapia fundamental.</li><li>El iSGLT2 puede iniciarse en el hospital tras la estabilización.</li><li>Control en 1-2 semanas con laboratorio y plan de titulación escrito.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 6, '{"text":"Para profundizar","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
