  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 8, '{"url":"https://doi.org/10.1016/j.jchf.2024.08.004","title":"Inpatient use of guideline-directed medical therapy during heart failure hospitalizations among community-based health systems. JACC Heart Fail. 2024.","description":"Artículo científico · DOI 10.1016/j.jchf.2024.08.004"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 9, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 10, '{"html":"<ol><li>McDonagh TA, Metra M, Adamo M, et al. 2023 Focused Update of the 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2023;44(37):3627-39. <a href=\"https://doi.org/10.1093/eurheartj/ehad195\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehad195</a></li><li>Køber L, Adamo M, Ruwald AC, et al. 2026 ESC Guidelines for the management of heart failure. Eur Heart J. 2026;47(38):5346. <a href=\"https://doi.org/10.1093/eurheartj/ehag100\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehag100</a></li><li>McDonagh TA, Metra M, Adamo M, et al. 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2021;42(36):3599-726. <a href=\"https://doi.org/10.1093/eurheartj/ehab368\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehab368</a></li><li>Inpatient use of guideline-directed medical therapy during heart failure hospitalizations among community-based health systems. JACC Heart Fail. 2024. <a href=\"https://doi.org/10.1016/j.jchf.2024.08.004\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jchf.2024.08.004</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Terapia médica adicional en FEVI reducida: ivabradina, vericiguat y digoxina/digitoxina', 'Clase 3 · Terapia médica adicional en FEVI reducida', 3, 'video', 8, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Compara indicaciones, dosis, evidencia reciente (DIGIT-HF, VICTOR) e interacciones de ivabradina, vericiguat y glucósidos cardíacos.</p><p><strong>Objetivo:</strong> Comparar el lugar en la terapia, la dosis y la seguridad de ivabradina, vericiguat y glucósidos cardíacos.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=qR8n3OulHV4","provider":"youtube","videoId":"qR8n3OulHV4","title":"Digoxina ¿Cuándo y cómo debemos administrarla?  Tu Farmacéutico Informa","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Son terapias para pacientes seleccionados que siguen sintomáticos pese a la terapia fundamental. La Guía ESC 2026 los agrupa como terapia médica adicional.</p><p>Ivabradina. Reduce la frecuencia cardíaca al inhibir la corriente If del nodo sinusal, sin bajar la presión. La guía ESC 2021 la recomienda (IIa) en pacientes sintomáticos con FEVI ≤35 %, en ritmo sinusal y con frecuencia en reposo ≥70 lpm pese a la dosis máxima tolerada de betabloqueador (o si este está contraindicado). Dosis de la tabla ESC 2021: 5 mg cada 12 h hasta 7,5 mg cada 12 h. No sirve en fibrilación auricular y no reemplaza al betabloqueador.</p><p>Vericiguat. Estimulador de la guanilato ciclasa soluble. En la guía ESC 2021 tiene recomendación IIb en pacientes en clase NYHA II-IV con empeoramiento reciente de la IC pese al tratamiento (ensayo VICTORIA). Dosis de la tabla ESC 2021: 2,5 mg al día hasta 10 mg al día. El ensayo VICTOR (2025), en pacientes estables sin empeoramiento reciente, no mostró una reducción significativa de su objetivo principal; sus análisis de mortalidad se siguen discutiendo.</p><p>Digoxina y digitoxina. Aumentan la contractilidad y frenan la conducción AV. En 2021 la digoxina tenía recomendación IIb en ritmo sinusal. El ensayo DIGIT-HF (2025) evaluó la digitoxina en FEVIr avanzada y, según sus resúmenes, mejoró los desenlaces; la Guía ESC 2026 sube a IIa la recomendación de digoxina o digitoxina en pacientes seleccionados con FEVIr sintomática pese a terapia fundamental óptima. Dosis de digoxina en la tabla ESC 2021: 62,5-250 µg al día, buscando concentraciones séricas bajas. Es de margen terapéutico estrecho: la hipopotasemia por diuréticos favorece la toxicidad (ficha técnica de furosemida), el carvedilol aumenta su exposición hasta 20 % y la espironolactona prolonga su semivida (fichas técnicas respectivas). Debe ajustarse a la función renal y al peso.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>En Tuluá, un paciente de 80 años con FEVIr toma digoxina 0,25 mg al día y furosemida; refiere náuseas y visión amarillenta, y su potasio es de 3,2 mmol/L. El QF sospecha toxicidad digitálica favorecida por la hipopotasemia, alerta al médico para solicitar digoxinemia y ECG, y luego reporta el evento al INVIMA.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li><strong>Ivabradina:</strong> ritmo sinusal, frecuencia ≥70 lpm y FEVI ≤35 % pese a betabloqueador.</li><li><strong>Vericiguat:</strong> empeoramiento reciente pese a tratamiento; VICTOR no confirmó beneficio en estables.</li><li><strong>Digoxina/digitoxina:</strong> IIa en ESC 2026 para casos seleccionados; vigilar potasio, función renal e interacciones.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 6, '{"text":"Para profundizar","level":2}'::jsonb);
