  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>Køber L, Adamo M, Ruwald AC, et al. 2026 ESC Guidelines for the management of heart failure. Eur Heart J. 2026;47(38):5346. <a href=\"https://doi.org/10.1093/eurheartj/ehag100\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehag100</a></li><li>McDonagh TA, Metra M, Adamo M, et al. 2023 Focused Update of the 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2023;44(37):3627-39. <a href=\"https://doi.org/10.1093/eurheartj/ehad195\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehad195</a></li><li>Solomon SD, et al. Finerenone in heart failure with mildly reduced or preserved ejection fraction. N Engl J Med. 2024;391(16). <a href=\"https://doi.org/10.1056/NEJMoa2407107\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1056/NEJMoa2407107</a></li><li>American College of Cardiology Solution Set Oversight Committee. Management of Heart Failure With Preserved Ejection Fraction: 2026 ACC Expert Consensus Decision Pathway. J Am Coll Cardiol. 2026. <a href=\"https://doi.org/10.1016/j.jacc.2026.06.018\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.jacc.2026.06.018</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Caso: mujer de 74 años en Bucaramanga con FEVI preservada, obesidad, diabetes y fibrilación auricular', 'Clase 4 · IC con FEVI preservada', 6, 'video', 7, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta un plan farmacoterapéutico integral para una paciente con FEVIp y múltiples comorbilidades, priorizando según evidencia y seguridad.</p><p><strong>Objetivo:</strong> Ejecutar un plan farmacoterapéutico priorizado para una paciente con IC con FEVI preservada y comorbilidades.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=2BtL4tDy5ec","provider":"youtube","videoId":"2BtL4tDy5ec","title":"Tirzepatida: una nueva esperanza para la IC con fracción de eyección preservada y obesidad","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Caso. Mujer de 74 años, de Bucaramanga. FEVI 58 %, IMC 34 kg/m², diabetes tipo 2, hipertensión y fibrilación auricular permanente. NYHA II-III, edemas leves. Presión 146/84 mmHg, frecuencia 88 lpm. Toma furosemida 40 mg, losartán 50 mg, bisoprolol 5 mg, apixabán 5 mg cada 12 h, metformina 850 mg cada 12 h y glibenclamida 5 mg al día. TFG 55, potasio 4,4 mmol/L, HbA1c 8,1 %, NT-proBNP 900 pg/mL.</p><p>Paso 1, clasificar. IC con FEVIp (≥50 %), etapa C, NYHA II-III, con congestión leve.</p><p>Paso 2, terapia con evidencia en FEVIp (ESC 2026). Proponer iSGLT2 (por ejemplo, dapagliflozina 10 mg; TFG ≥25), que además ayuda al control glucémico. Proponer un ARM (espironolactona 25 mg si potasio ≤5,0 y creatinina ≤2,5 mg/dL, según ficha técnica), con potasio y creatinina a la semana.</p><p>Paso 3, obesidad. La Guía ESC 2026 recomienda (IIa) semaglutida o tirzepatida en FEVIp sintomática con obesidad; STEP-HFpEF DM (2024) estudió semaglutida en pacientes con diabetes y SUMMIT (2025) tirzepatida. El QF verifica la indicación aprobada en el inserto INVIMA, la cobertura y el uso conjunto con hipoglucemiantes.</p><p>Paso 4, seguridad glucémica. Al agregar iSGLT2 (y eventualmente un aGLP-1) con glibenclamida aumenta el riesgo de hipoglucemia; sugerir al médico reducir o retirar la sulfonilurea.</p><p>Paso 5, comorbilidades. Presión sobre la meta (&lt;130 mmHg sistólica): considerar subir losartán. Frecuencia de 88 lpm en fibrilación auricular: valorar ajustar bisoprolol. Mantener apixabán y verificar su dosis según edad, peso y creatinina.</p><p>Paso 6, educación y seguimiento. Peso diario, sal, signos de alarma, higiene genital con iSGLT2, y control en 2 semanas.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p><strong>El QF presenta la propuesta en la junta del programa:</strong> iniciar dapagliflozina y retirar glibenclamida en la misma visita; espironolactona en 2 semanas; valorar aGLP-1 según inserto y cobertura; ajustar losartán. Cada cambio queda con su control programado.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>En FEVIp, iniciar iSGLT2 y ARM según ESC 2026.</li><li>Ajustar sulfonilureas al añadir iSGLT2 o aGLP-1.</li><li>Controlar presión, frecuencia y anticoagulación como parte del tratamiento de la IC.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 6, '{"text":"Para profundizar","level":2}'::jsonb);
