  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>Køber L, Adamo M, Ruwald AC, et al. 2026 ESC Guidelines for the management of heart failure. Eur Heart J. 2026;47(38):5346. <a href=\"https://doi.org/10.1093/eurheartj/ehag100\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehag100</a></li><li>McDonagh TA, Metra M, Adamo M, et al. 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure. Eur Heart J. 2021;42(36):3599-726. <a href=\"https://doi.org/10.1093/eurheartj/ehab368\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1093/eurheartj/ehab368</a></li><li>Tian X, et al. Improving therapeutic outcomes in heart failure with reduced nonvalvular ejection fraction: a clinical study of heart failure education intervention. Clin Cardiol. 2024. <a href=\"https://doi.org/10.1002/clc.24265\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1002/clc.24265</a></li><li>Stolfo D, et al. How to handle polypharmacy in heart failure. A clinical consensus statement of the Heart Failure Association of the ESC. Eur J Heart Fail. 2025. <a href=\"https://doi.org/10.1002/ejhf.3642\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1002/ejhf.3642</a></li></ol>"}'::jsonb);
