  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta un plan farmacoterapéutico integral: conciliación, optimización de la terapia fundamental, desprescripción, seguridad, educación y farmacovigilancia.</p><p><strong>Objetivo:</strong> Ejecutar un plan farmacoterapéutico integral para un paciente complejo con IC, aplicando lo aprendido en el curso.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=x2lOeFIr8ps","provider":"youtube","videoId":"x2lOeFIr8ps","title":"Insuficiencia cardíaca en el adulto mayor cómo optimizar el tratamiento: Fragilidad y polifarmacia","transcriptHtml":""}'::jsonb);
