  VALUES (v_clase, 'encabezado', 11, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 12, '{"html":"<ol><li>Global Initiative for Asthma. GINA 2026 Summary Guide for asthma management and prevention (adults, adolescents and children 6-11 years). GINA; julio 2026 [consultado 27 oct 2026].</li><li>Organización Mundial de la Salud. Asma: nota descriptiva. OMS; 28 abr 2026 [consultado 27 oct 2026].</li><li>Safwan MA, Goel N, Kumar R. Asthma, COPD, and asthma–COPD overlap: A comparative study of inflammatory biomarkers and quality of life. Lung India. 2026;43(4):364-70. <a href=\"https://doi.org/10.4103/lungindia.lungindia_605_25\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.4103/lungindia.lungindia_605_25</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'EPOC: definición, factores de riesgo y diagnóstico espirométrico según GOLD 2026', 'Clase 2 · Asma y EPOC: definición y diagnóstico', 2, 'video', 20, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Describe la definición de EPOC, sus factores de riesgo (tabaco y biomasa) y la confirmación espirométrica.</p><p><strong>Objetivo:</strong> Describir la definición, los factores de riesgo y el diagnóstico espirométrico de la EPOC según el informe GOLD 2026.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=4CVlOjtOxi4","provider":"youtube","videoId":"4CVlOjtOxi4","title":"GUÍA GOLD 2026: Lo NUEVO que TODO médico debe conocer - PARTE I","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>GOLD define la EPOC como una condición pulmonar heterogénea con síntomas respiratorios crónicos (disnea, tos, expectoración, exacerbaciones) causada por alteraciones de la vía aérea o de los alvéolos, que producen una obstrucción persistente y a menudo progresiva del flujo aéreo. Se debe sospechar en personas con disnea, tos o expectoración crónica, infecciones respiratorias bajas a repetición o exposición a factores de riesgo.</p><p>Los factores de riesgo son el tabaco, el humo de biomasa (leña o carbón para cocinar), el polvo y los químicos ocupacionales, el asma en la infancia y eventos tempranos como bajo peso al nacer o infecciones graves en la niñez. La OMS indica que el tabaco explica 30-40 % de los casos en países de ingresos bajos y medios, donde la contaminación del aire doméstico tiene gran peso: un dato relevante en zonas rurales de Colombia donde todavía se cocina con leña. El déficit de alfa-1 antitripsina causa EPOC de inicio temprano.</p><p>El diagnóstico exige espirometría con una relación FEV1/FVC posbroncodilatador menor de 0,70 en un contexto clínico compatible; GOLD 2026 lo califica como obligatorio. La espirometría prebroncodilatador sirve para descartar. La gravedad de la obstrucción se clasifica por el FEV1 posbroncodilatador en GOLD 1 (≥80 % del predicho), 2 (50-79 %), 3 (30-49 %) y 4 (&lt;30 %). La evaluación inicial combina obstrucción, síntomas (mMRC o CAT) y riesgo de exacerbaciones.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un agricultor de 66 años de Ráquira (Boyacá), nunca fumador, cocinó con leña durante 30 años. Tiene tos con flema cada mañana y se ahoga al subir lomas. Su espirometría posbroncodilatador muestra FEV1/FVC de 0,61 y FEV1 de 62 %: EPOC GOLD 2. El QF registra la exposición a biomasa como factor de riesgo y recuerda que no fumar no descarta la EPOC.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>Sin espirometría posbroncodilatador con FEV1/FVC &lt;0,70 no hay diagnóstico de EPOC.</li><li>El humo de leña es un factor de riesgo importante en Colombia, además del tabaco.</li><li>GOLD 1-4 mide la obstrucción; el tratamiento se decide con síntomas y exacerbaciones.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 6, '{"tone":"advertencia","title":"Nota de actualización (oct. 2026)","html":"<p>GOLD 2026 reorganizó el informe en seis capítulos, añadió un algoritmo de búsqueda activa de casos y un capítulo sobre inteligencia artificial.</p>"}'::jsonb);
