  VALUES (v_clase, 'enlace', 8, '{"url":"https://ginasthma.org/wp-content/uploads/2026/07/GINA-Summary-Guide-2026-WEB-WMS.pdf","title":"GINA 2026 Summary Guide: Asthma Management and Prevention for adults, adolescents and children 6-11 years","description":"PDF · Global Initiative for Asthma (en inglés) · 2026"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 9, '{"url":"https://doi.org/10.1002/resp.70333","title":"Ferry OR, Yang IA. The Era of Precision Medicine: Exacerbation Phenotyping to Determine the Role of Inhaled Corticosteroids in COPD? Respirology. 2026.","description":"Artículo científico · DOI 10.1002/resp.70333"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 10, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>AEMPS. Ficha técnica Symbicort Turbuhaler 160 microgramos/4,5 microgramos/inhalación polvo para inhalación. CIMA; revisión febrero 2021 [consultado 27 oct 2026].</li><li>Global Initiative for Asthma. GINA 2026 Summary Guide for asthma management and prevention (adults, adolescents and children 6-11 years). GINA; julio 2026 [consultado 27 oct 2026].</li><li>Ferry OR, Yang IA. The Era of Precision Medicine: Exacerbation Phenotyping to Determine the Role of Inhaled Corticosteroids in COPD? Respirology. 2026. <a href=\"https://doi.org/10.1002/resp.70333\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1002/resp.70333</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Montelukast y otros controladores: eficacia comparada y seguridad neuropsiquiátrica', 'Clase 3 · Corticoides inhalados y otros controladores', 4, 'manual', 5, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Compara montelukast con los ICS, resume su ficha técnica y el informe de seguridad del INVIMA de 2024.</p><p><strong>Objetivo:</strong> Comparar el montelukast y otros controladores no inhalados con los corticoides inhalados, incluida su seguridad neuropsiquiátrica.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 1, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 2, '{"html":"<p>El montelukast (ATC R03DC03) bloquea el receptor de leucotrienos. Según su ficha técnica, la presentación de 10 mg está indicada, a partir de los 15 años, como tratamiento añadido en asma persistente leve a moderada no controlada con ICS y SABA a demanda, y para prevenir la broncoconstricción por ejercicio; también puede aliviar la rinitis alérgica estacional en esos pacientes. La dosis es 10 mg una vez al día por la noche. Existen presentaciones pediátricas (4 y 5 mg). No sirve para crisis agudas y no debe reemplazar de forma brusca a los corticoides. Las RAM muy frecuentes son infecciones respiratorias altas; frecuentes: cefalea, dolor abdominal, diarrea, náuseas, fiebre, erupción y elevación de transaminasas. El fenobarbital reduce su exposición cerca de 40 %.</p><p><strong>Seguridad:</strong> se han reportado eventos neuropsiquiátricos en todas las edades (alteraciones del sueño, pesadillas, ansiedad, depresión, agresividad, ideación suicida). El INVIMA, en su Informe de seguridad 349-2024 (5-nov-2024), pidió informar el riesgo, preguntar antecedentes de depresión o ideación suicida antes de iniciar, suspender ante síntomas nuevos y reportar al Programa Nacional de Farmacovigilancia.</p><p><strong>Comparación:</strong> GINA 2026 considera los antileucotrienos menos eficaces que el ICS; en niños de 6-11 años son alternativa en el paso 2 con la advertencia neuropsiquiátrica. Teofilina y salbutamol orales no se recomiendan. En EPOC, el roflumilast y la azitromicina son opciones de seguimiento en perfiles seleccionados (unidad 4).</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 3, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>La madre de un niño de 8 años en Neiva cuenta que, desde que inició montelukast 5 mg, el niño tiene pesadillas e irritabilidad. El QF reconoce la reacción descrita, la orienta para consultar pronto al pediatra, reporta el caso al INVIMA y recuerda que el control del asma se basa en el ICS.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"importante","title":"Puntos clave","html":"<ol><li><strong>Montelukast:</strong> añadido o alternativa menos eficaz que el ICS; no sirve en crisis.</li><li>Preguntar por antecedentes psiquiátricos y vigilar sueño y ánimo (INVIMA 349-2024).</li><li>Teofilina y salbutamol orales no se recomiendan en asma.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 5, '{"text":"Para profundizar","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 6, '{"url":"https://cima.aemps.es/cima/dochtml/ft/61980/FT_61980.html","title":"Ficha técnica Singulair 10 mg comprimidos recubiertos con película (montelukast)","description":"Página web · AEMPS - CIMA · 2025"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
