  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 8, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 9, '{"html":"<ol><li>AEMPS. Ficha técnica Singulair 10 mg comprimidos recubiertos con película. CIMA; revisión octubre 2025 [consultado 27 oct 2026].</li><li>INVIMA. Informe de seguridad No. 349-2024: Riesgo de reacciones neuropsiquiátricas asociadas al tratamiento con montelukast. Bogotá: INVIMA; 5 nov 2024.</li><li>Global Initiative for Asthma. GINA 2026 Summary Guide for asthma management and prevention (adults, adolescents and children 6-11 years). GINA; julio 2026 [consultado 27 oct 2026].</li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Caso: paciente con asma que solo usa salbutamol y presenta sobreuso', 'Clase 3 · Corticoides inhalados y otros controladores', 5, 'video', 32, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Aplica el análisis del sobreuso de SABA, la valoración del control y la intervención educativa y de remisión del QF.</p><p><strong>Objetivo:</strong> Aplicar el análisis farmacoterapéutico ante un paciente con asma que usa solo SABA y presenta sobreuso.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=wHipW8Amxtc","provider":"youtube","videoId":"wHipW8Amxtc","title":"¿Salbutamol solo en asma? Riesgo o Beneficio","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p><strong>Paso 1:</strong> cuantificar el uso de SABA (inhaladores dispensados en 12 meses y disparos por semana). Paso 2: evaluar el control con preguntas de GINA o el ACT (síntomas diurnos, despertares, limitación, uso de rescate). Paso 3: buscar exacerbaciones y uso de corticoide oral. Paso 4: revisar técnica, desencadenantes y comorbilidades (rinitis). Paso 5: comunicar al médico los hallazgos con una propuesta basada en GINA y educar sin alarmar.</p><p><strong>Caso:</strong> Laura, 28 años, Cali. Asma desde la adolescencia. Solo usa salbutamol inhalado, que compra sin fórmula: 4 inhaladores de 200 dosis en los últimos 6 meses (ritmo de 8 al año). Se despierta 2 noches por semana con tos y usa el inhalador casi a diario. Recibió prednisolona en urgencias hace 3 meses. Técnica: dispara y luego inhala, sin cámara. Tiene rinitis sin tratamiento.</p><p><strong>Análisis:</strong> Asma no controlada con sobreuso de SABA. GINA 2026 señala que usar 3 o más inhaladores de SABA al año se asocia con exacerbaciones más graves y 12 o más con muerte por asma; además, el SABA regular aumenta la inflamación y reduce su propio efecto. Todo paciente con asma debe recibir tratamiento con ICS. El estudio SABINA III, citado por investigadores colombianos, mostró que 38 % de los pacientes recibían más de 3 inhaladores de SABA al año y 20 % lo compraban sin fórmula.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>El QF explica a Laura, con lenguaje sencillo, que el salbutamol alivia pero no controla la inflamación. Corrige la técnica con cámara, la remite con prioridad al médico con una nota: uso de 8 inhaladores al año, una exacerbación con corticoide oral, síntomas nocturnos y propuesta de tratamiento con ICS-formoterol (vía 1 de GINA, MART por la exacerbación reciente) o la alternativa que el médico defina. Acuerda un control en 4 semanas con el ACT.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>Contar inhaladores de SABA dispensados es un indicador simple de riesgo.</li><li>El asma no se trata solo con SABA; requiere ICS.</li><li>La intervención del QF combina educación, técnica y remisión documentada.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
