  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 10, '{"url":"https://doi.org/10.1183/23120541.00494-2024","title":"Levy ML, Crooks MG. Anti-inflammatory reliever therapy (AIR) for asthma. ERJ Open Res. 2024;10(5):00494-2024.","description":"Artículo científico · DOI 10.1183/23120541.00494-2024"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 11, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 12, '{"html":"<ol><li>Global Initiative for Asthma. Global Strategy for Asthma Management and Prevention, 2026 update. GINA; publicado 5 may 2026 [consultado 27 oct 2026]. Disponible en: <a href=\"https://ginasthma.org/2026-gina-strategy-report/\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">https://ginasthma.org/2026-gina-strategy-report/</a></li><li>Global Initiative for Asthma. GINA 2026 Summary Guide for asthma management and prevention (adults, adolescents and children 6-11 years). GINA; julio 2026 [consultado 27 oct 2026].</li><li>Guideline Central. GINA 2026 Strategy for Asthma Management and Prevention: key changes. Guideline Spotlight; 19 may 2026 [consultado 27 oct 2026].</li><li>Levy ML, Crooks MG. Anti-inflammatory reliever therapy (AIR) for asthma. ERJ Open Res. 2024;10(5):00494-2024. <a href=\"https://doi.org/10.1183/23120541.00494-2024\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1183/23120541.00494-2024</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Vías 1 y 2 de GINA 2026 en adultos y adolescentes: pasos 1 a 5', 'Clase 2 · Tratamiento escalonado del asma', 1, 'video', 70, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Interpreta los cinco pasos de las vías 1 (ICS-formoterol) y 2 (ICS-SABA o SABA) y la relación entre guía e inserto.</p><p><strong>Objetivo:</strong> Interpretar los pasos 1 a 5 de las vías 1 y 2 de GINA 2026 para adultos y adolescentes.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=up19QGigkd4","provider":"youtube","videoId":"up19QGigkd4","title":"Nueva Guía de Asma GINA 2026 #AlDíaConLasGuías","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>Vía 1 (preferida, rescate con ICS-formoterol):</p><ul><li><strong>Pasos 1-2:</strong> solo rescate antiinflamatorio (AIR) con ICS-formoterol a dosis baja a necesidad (por ejemplo, budesonida-formoterol, 1 inhalación cuando hay síntomas).</li><li><strong>Paso 3:</strong> MART con ICS-formoterol a dosis baja: 1 inhalación mañana y noche más 1 a necesidad.</li><li><strong>Paso 4:</strong> MART a dosis media: 2 inhalaciones mañana y noche más 1 a necesidad.</li><li><strong>Paso 5:</strong> remitir para valoración experta y fenotipo; opciones: LAMA añadido, prueba de ICS-formoterol a dosis alta y biológicos.</li></ul><p>La ventaja es usar un solo inhalador en todos los pasos y que cada rescate aporte corticoide.</p><p>Vía 2 (alternativa, rescate con ICS-SABA o SABA):</p><ul><li><strong>Paso 1:</strong> AIR con ICS-SABA a dosis baja; si solo hay SABA, tomar una dosis baja de ICS cada vez que se usa el SABA.</li><li><strong>Paso 2:</strong> ICS a dosis baja de mantenimiento.</li><li><strong>Paso 3:</strong> ICS-LABA a dosis baja.</li><li><strong>Paso 4:</strong> ICS-LABA a dosis media.</li><li><strong>Paso 5:</strong> remitir, igual que la vía 1.</li></ul><p>Antes de subir un paso se revisan técnica, adherencia, exposición y comorbilidades.</p><p><strong>Para el QF es clave conocer el inserto aprobado:</strong> la ficha técnica de referencia de budesonida-formoterol 160/4,5 indica el producto en asma desde los 12 años, en mantenimiento o como MART, y dice que no se recomienda en el tratamiento inicial del asma. GINA, en cambio, propone AIR desde el paso 1. En Colombia prevalece el inserto INVIMA, por lo que el uso como AIR debe verificarse frente a la indicación aprobada.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un estudiante de 19 años en Tunja tiene síntomas dos veces al mes y usa solo salbutamol. Su médico lo pasa a la vía 1, paso 2: budesonida-formoterol a necesidad. El QF le explica que ese inhalador alivia y a la vez controla la inflamación, y que debe consultar si necesita muchas inhalaciones en un día.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li><strong>Vía 1:</strong> un solo inhalador de ICS-formoterol en todos los pasos (AIR en 1-2, MART en 3-4).</li><li><strong>Vía 2:</strong> rescate con ICS-SABA o SABA y mantenimiento con ICS o ICS-LABA.</li><li>Verificar siempre la indicación del inserto INVIMA frente a la recomendación de la guía.</li></ol>"}'::jsonb);
