  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 12, '{"html":"<ol><li>Global Initiative for Asthma. GINA 2026 Summary Guide for asthma management and prevention (adults, adolescents and children 6-11 years). GINA; julio 2026 [consultado 27 oct 2026].</li><li>Guideline Central. GINA 2026 Strategy for Asthma Management and Prevention: key changes. Guideline Spotlight; 19 may 2026 [consultado 27 oct 2026].</li><li>AEMPS. Ficha técnica Symbicort Turbuhaler 160 microgramos/4,5 microgramos/inhalación polvo para inhalación. CIMA; revisión febrero 2021 [consultado 27 oct 2026].</li><li>Torres-Duque CA, Perna-Reyes I, Alí-Munive A. How to implement the anti-inflammatory reliever treatment proposed by the Global Initiative for Asthma in low- and middle-income countries. Explor Asthma Allergy. 2024;2(3):219-32. <a href=\"https://doi.org/10.37349/eaa.2024.00042\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.37349/eaa.2024.00042</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'MART con budesonida-formoterol: dosificación, límites y educación', 'Clase 2 · Tratamiento escalonado del asma', 2, 'video', 10, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Aplica las dosis y los límites diarios de MART según la ficha técnica y GINA 2026, y la equivalencia entre dosis medida y liberada.</p><p><strong>Objetivo:</strong> Aplicar la terapia de mantenimiento y rescate (MART) con budesonida-formoterol: dosis, límites, interpretación de concentraciones y educación del paciente.</p>"}'::jsonb);
