  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 9, '{"url":"https://doi.org/10.4103/lungindia.lungindia_46_25","title":"Malhotra N, Rathi V, Ish P. Anti-inflammatory reliever therapy for asthma in India – Can we be SMARTer. Lung India. 2025;42(5):477-9.","description":"Artículo científico · DOI 10.4103/lungindia.lungindia_46_25"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 10, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>AEMPS. Ficha técnica Symbicort Turbuhaler 160 microgramos/4,5 microgramos/inhalación polvo para inhalación. CIMA; revisión febrero 2021 [consultado 27 oct 2026].</li><li>Global Initiative for Asthma. GINA 2026 Summary Guide for asthma management and prevention (adults, adolescents and children 6-11 years). GINA; julio 2026 [consultado 27 oct 2026].</li><li>Malhotra N, Rathi V, Ish P. Anti-inflammatory reliever therapy for asthma in India – Can we be SMARTer. Lung India. 2025;42(5):477-9. <a href=\"https://doi.org/10.4103/lungindia.lungindia_46_25\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.4103/lungindia.lungindia_46_25</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Asma en niños de 6 a 11 años: pasos de tratamiento, crisis y dispositivos', 'Clase 2 · Tratamiento escalonado del asma', 3, 'video', 88, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Interpreta los pasos de GINA 2026 para niños de 6-11 años, la dosis de prednisolona en crisis y el uso de cámaras.</p><p><strong>Objetivo:</strong> Interpretar el tratamiento escalonado del asma en niños de 6 a 11 años según GINA 2026 y sus particularidades de seguridad y dispositivos.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=R0218ZX8cA4","provider":"youtube","videoId":"R0218ZX8cA4","title":"Actualización en asma pediátrica GINA 2026 - Grupo de interés en pediatría FUSM","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>GINA 2026 propone para niños de 6-11 años:</p><ul><li><strong>Paso 1:</strong> AIR con ICS-formoterol a dosis baja a necesidad, o ICS-SABA a dosis baja (en combinación o inhaladores separados).</li><li><strong>Paso 2:</strong> ICS diario a dosis baja más rescate a necesidad. El antileucotrieno (montelukast) es una alternativa menos eficaz, con advertencias neuropsiquiátricas.</li><li><strong>Paso 3:</strong> ICS a dosis media, ICS-LABA a dosis baja o MART con ICS-formoterol a dosis baja.</li><li><strong>Paso 4:</strong> ICS-LABA a dosis media, MART (con el doble de la dosis del paso 3) o remisión a especialista; el tiotropio es una opción añadida.</li><li><strong>Paso 5:</strong> remitir para valoración del fenotipo.</li></ul><p>La novedad de 2026 es incluir AIR con budesonida-formoterol en los pasos 1 y 2: en niños de 5 a 15 años, el rescate antiinflamatorio a dosis baja redujo casi a la mitad las exacerbaciones moderadas a graves frente al SABA solo.</p><p>En exacerbaciones, la prednisolona se dosifica a 1-2 mg/kg/día (máximo 40 mg) por 3-5 días, y en menores de 18 años GINA recomienda usar una escala clínica validada (como PRAM). La técnica es crítica: los niños deben usar inhalador presurizado con cámara espaciadora. La OMS recuerda que una cámara hecha con una botella plástica de 500 mL puede funcionar casi como una comercial cuando no hay otra opción.</p><p>En Colombia, la GPC de asma del MinSalud (2013) sigue publicada; conviene contrastarla con GINA 2026. Antes de dispensar, el QF verifica la edad aprobada de cada presentación en el inserto INVIMA (por ejemplo, la ficha de referencia de budesonida-formoterol 160/4,5 no recomienda MART en menores de 12 años).</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Tomás, de 9 años, en Neiva, usa salbutamol y montelukast 5 mg; tuvo dos crisis este año y su mamá reporta pesadillas. El QF reporta la posible reacción al INVIMA, enseña la técnica con cámara y remite al pediatra resaltando que el niño no recibe ICS.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>En niños también todo tratamiento debe incluir ICS; montelukast es alternativa menos eficaz.</li><li>GINA 2026 incluye AIR con budesonida-formoterol en pasos 1-2 para 6-11 años.</li><li><strong>Prednisolona en crisis:</strong> 1-2 mg/kg/día, máximo 40 mg, 3-5 días.</li></ol>"}'::jsonb);
