  VALUES (v_clase, 'enlace', 7, '{"url":"https://ginasthma.org/wp-content/uploads/2026/07/GINA-Summary-Guide-2026-WEB-WMS.pdf","title":"GINA 2026 Summary Guide: Asthma Management and Prevention for adults, adolescents and children 6-11 years","description":"PDF · Global Initiative for Asthma (en inglés) · 2026"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 8, '{"url":"https://cima.aemps.es/cima/dochtml/ft/69589/FT_69589.html","title":"Ficha técnica Spiriva Respimat 2,5 microgramos solución para inhalación","description":"Página web · AEMPS - CIMA · 2024"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 9, '{"url":"https://doi.org/10.1080/02770903.2026.2706355","title":"Quaranta VN, Amoroso G, Marinelli A, et al. Beyond biologics: background inhaled therapy shapes remission in severe asthma. J Asthma. 2026:1-10.","description":"Artículo científico · DOI 10.1080/02770903.2026.2706355"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 10, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>Global Initiative for Asthma. GINA 2026 Summary Guide for asthma management and prevention (adults, adolescents and children 6-11 years). GINA; julio 2026 [consultado 27 oct 2026].</li><li>Guideline Central. GINA 2026 Strategy for Asthma Management and Prevention: key changes. Guideline Spotlight; 19 may 2026 [consultado 27 oct 2026].</li><li>AEMPS. Ficha técnica Spiriva Respimat 2,5 microgramos solución para inhalación. CIMA; revisión diciembre 2024 [consultado 27 oct 2026].</li><li>Quaranta VN, Amoroso G, Marinelli A, et al. Beyond biologics: background inhaled therapy shapes remission in severe asthma. J Asthma. 2026:1-10. <a href=\"https://doi.org/10.1080/02770903.2026.2706355\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1080/02770903.2026.2706355</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Biológicos en asma grave: anti-IgE, anti-IL-5, anti-IL-4Rα y anti-TSLP', 'Clase 3 · Asma de difícil control y asma grave', 5, 'video', 8, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Compara los biológicos por diana, edad mínima y fenotipo, y describe las tareas del QF en su gestión.</p><p><strong>Objetivo:</strong> Comparar los biológicos disponibles para el asma grave según su diana, edad mínima y fenotipo, y el papel del QF en su uso.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=J1O7Lhw6OJo","provider":"youtube","videoId":"J1O7Lhw6OJo","title":"Congreso SEPAR: los biológicos y la remisión del asma grave no controlada","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>GINA 2026 agrupa los biológicos para el asma grave así:</p><ul><li><strong>Anti-IgE:</strong> omalizumab (y su biosimilar), para asma alérgica desde los 6 años.</li><li><strong>Anti-IL-5 o su receptor:</strong> reslizumab intravenoso (18 años o más), mepolizumab subcutáneo (6 años o más), benralizumab y depemokimab (12 años o más). Indicados en asma eosinofílica.</li><li><strong>Anti-receptor alfa de IL-4:</strong> dupilumab, desde los 6 años, en inflamación eosinofílica o tipo 2, o en asma dependiente de corticoide oral.</li><li><strong>Anti-TSLP:</strong> tezepelumab, desde los 12 años.</li></ul><p>Depemokimab y el omalizumab biosimilar son incorporaciones de 2026. GINA añadió una tabla de indicaciones no asmáticas de cada clase (otras enfermedades tipo 2), útil cuando el paciente tiene comorbilidades, y un árbol de decisión más claro.</p><p>La elección depende del fenotipo (alérgico, eosinofílico, tipo 2, dependiente de corticoide oral), de los biomarcadores, de las comorbilidades, de la frecuencia de aplicación y del acceso. Revisiones de 2026 resaltan la remisión clínica (sin exacerbaciones ni corticoide oral, con buen control y función pulmonar estable) como meta posible en una parte de los pacientes.</p><p><strong>El QF participa en:</strong> verificar criterios y documentos para la autorización y la financiación (confirmar si la tecnología está financiada con la UPC o por otro mecanismo), garantizar la cadena de frío, entrenar la autoaplicación, vigilar reacciones en el sitio de inyección e hipersensibilidad, reportar eventos adversos y evaluar la respuesta con el especialista (exacerbaciones, uso de corticoide oral, ACT, FEV1).</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>Un hombre de 42 años en Bogotá con asma grave eosinofílica (eosinófilos 600 células/µL), poliposis nasal y dos ciclos de corticoide oral al año inicia un anti-IL-5. El QF lo entrena en la autoinyección, le explica cómo transportar el medicamento refrigerado y programa la revisión de respuesta con el neumólogo.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li><strong>Cuatro clases:</strong> anti-IgE, anti-IL-5/5R, anti-IL-4Rα y anti-TSLP, con edades mínimas distintas.</li><li>El fenotipo y los biomarcadores orientan la elección.</li><li>El QF asegura cadena de frío, técnica de aplicación, farmacovigilancia y seguimiento de la respuesta.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 6, '{"tone":"advertencia","title":"Nota de actualización (oct. 2026)","html":"<p>GINA 2026 añadió depemokimab y el omalizumab biosimilar a la lista de biológicos para asma grave.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 7, '{"text":"Para profundizar","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 8, '{"url":"https://ginasthma.org/wp-content/uploads/2026/07/GINA-Summary-Guide-2026-WEB-WMS.pdf","title":"GINA 2026 Summary Guide: Asthma Management and Prevention for adults, adolescents and children 6-11 years","description":"PDF · Global Initiative for Asthma (en inglés) · 2026"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
