  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 10, '{"url":"https://doi.org/10.1080/02770903.2026.2644878","title":"Wang M, Jiang D. Biologics in severe asthma: from precision phenotyping to clinical remission. J Asthma. 2026;63(8):939-50.","description":"Artículo científico · DOI 10.1080/02770903.2026.2644878"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 11, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 12, '{"html":"<ol><li>Global Initiative for Asthma. GINA 2026 Summary Guide for asthma management and prevention (adults, adolescents and children 6-11 years). GINA; julio 2026 [consultado 27 oct 2026].</li><li>Guideline Central. GINA 2026 Strategy for Asthma Management and Prevention: key changes. Guideline Spotlight; 19 may 2026 [consultado 27 oct 2026].</li><li>Wang M, Jiang D. Biologics in severe asthma: from precision phenotyping to clinical remission. J Asthma. 2026;63(8):939-50. <a href=\"https://doi.org/10.1080/02770903.2026.2644878\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1080/02770903.2026.2644878</a></li><li>Coyle LM, McDowell PJ, Heaney LG. Lessons learned regarding optimal use of biologics to achieve disease remission in severe asthma. Ann Allergy Asthma Immunol. 2026;136(5):520-8. <a href=\"https://doi.org/10.1016/j.anai.2026.02.008\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.anai.2026.02.008</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Caso: asma no controlada en el paso 4 con MART', 'Clase 3 · Asma de difícil control y asma grave', 6, 'manual', 358, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta la evaluación de control, técnica, adherencia, exposiciones y biomarcadores para proponer ajustes y remisión.</p><p><strong>Objetivo:</strong> Ejecutar la evaluación farmacoterapéutica de un paciente con asma no controlada en el paso 4 y proponer los siguientes pasos.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=YizT42xnWxs","provider":"youtube","videoId":"YizT42xnWxs","title":"Curso de actualización en Asma 2025","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p><strong>Secuencia sugerida:</strong> (1) confirmar el diagnóstico; (2) medir control (ACT) y riesgo (exacerbaciones, corticoide oral, uso de rescate); (3) revisar técnica con lista de chequeo del dispositivo; (4) estimar adherencia (registros de dispensación, preguntas abiertas); (5) identificar exposiciones y comorbilidades; (6) proponer ajustes y remisión; (7) definir indicadores de seguimiento.</p><p><strong>Caso:</strong> Andrés, 45 años, Medellín, trabaja en una carpintería. Asma desde los 20 años. Usa budesonida-formoterol 200/6 (dosis medida) en MART: 2 inhalaciones cada 12 horas más 3-4 inhalaciones de rescate al día. Recibió dos ciclos de prednisolona en el último año. ACT: 14. Exhala dentro del Turbuhaler antes de inhalar. Retira el inhalador cada 6 semanas (debería cada 30 días). Tiene rinitis sin tratamiento y fuma 5 cigarrillos al día. Eosinófilos: 450 células/µL; FeNO: 55 ppb.</p><p><strong>Análisis:</strong> Asma no controlada con riesgo alto (dos exacerbaciones con corticoide oral). Hay factores modificables: técnica con error crítico, adherencia cercana a 70 % al mantenimiento, tabaquismo, exposición a polvo de madera y rinitis sin tratar. Además, el uso de rescate se acerca al límite diario de la ficha (normalmente no más de 8 inhalaciones al día). Los biomarcadores sugieren inflamación tipo 2.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>El QF corrige la técnica (exhalar lejos del dispositivo, inhalación fuerte y profunda) y verifica dos veces; acuerda recordatorios para el mantenimiento; ofrece apoyo para dejar de fumar; recomienda protección respiratoria en el trabajo y remite al médico con un informe: ACT 14, dos ciclos de corticoide oral, eosinófilos 450 y FeNO 55, rinitis sin tratamiento y exposición laboral. Propone reevaluar en 4-6 semanas tras las correcciones; si persiste sin control, valorar el paso 5 (LAMA añadido o fenotipo para biológico). Acuerda un plan de acción escrito.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li>Corregir técnica, adherencia, tabaquismo y exposiciones antes de escalar.</li><li>Dos exacerbaciones con corticoide oral indican riesgo alto y necesidad de revisión.</li><li>Eosinófilos y FeNO elevados orientan hacia un fenotipo tipo 2 si se llega al paso 5.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 6, '{"text":"Para profundizar","level":2}'::jsonb);
