  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Compara escalar a triple terapia, cambiar dispositivo o retirar el ICS según exacerbaciones, eosinófilos y neumonías.</p><p><strong>Objetivo:</strong> Comparar las opciones de seguimiento en EPOC: escalar a triple terapia, cambiar dispositivo o molécula y retirar el corticoide inhalado.</p>"}'::jsonb);
