  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 11, '{"html":"<ol><li>Guideline Central. GINA 2026 Strategy for Asthma Management and Prevention: key changes. Guideline Spotlight; 19 may 2026 [consultado 27 oct 2026].</li><li>AEMPS. Ficha técnica Spiriva Respimat 2,5 microgramos solución para inhalación. CIMA; revisión diciembre 2024 [consultado 27 oct 2026].</li><li>Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide (v1.1, 20 nov 2025). GOLD; 2025 [consultado 27 oct 2026].</li><li>Udgiri R. Persistent inhaler technique errors in asthma and COPD: a systemic barrier to optimal pulmonary drug delivery. Next Res. 2026;3:101170. <a href=\"https://doi.org/10.1016/j.nexres.2025.101170\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.1016/j.nexres.2025.101170</a></li></ol>"}'::jsonb);
