  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'enlace', 10, '{"url":"https://www.minsalud.gov.co/sites/rid/Lists/BibliotecaDigital/RIDE/VS/PP/PAI/lineamiento-nal-vacunacion-influenza-estacional-cepa-sur-2026.pdf","title":"MinSalud. Lineamiento técnico y operativo nacional para la vacunación contra influenza estacional cepa sur 2026 (2026-04)","description":"Documento · Documento oficial · autoridad sanitaria"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 11, '{"text":"Referencias","level":3}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 12, '{"html":"<ol><li>Ministerio de Salud y Protección Social. Lineamiento técnico y operativo nacional para la vacunación contra influenza estacional cepa sur 2026, versión 1. Bogotá: MinSalud; abr 2026.</li><li>Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide (v1.1, 20 nov 2025). GOLD; 2025 [consultado 27 oct 2026].</li><li>Mattson M. Optimizing COPD Care: Updates from the 2026 GOLD Report. University of Minnesota College of Pharmacy; 4 mar 2026 [consultado 27 oct 2026].</li><li>Sacks HS; ACP Journal Club Editorial Team. In older adults, RSV prefusion F vaccine reduced hospitalization for RSV-related respiratory tract disease vs. no vaccine. Ann Intern Med. 2026;179(1):JC4. <a href=\"https://doi.org/10.7326/annals-25-05113-jc\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">doi:10.7326/annals-25-05113-jc</a></li></ol>"}'::jsonb);
  INSERT INTO aula_lessons (course_id, module_id, title, subtitle, sort_order, completion_rule, duration_minutes, is_required)
  VALUES (v_curso, v_unidad, 'Seguimiento farmacoterapéutico en asma y EPOC: herramientas e indicadores', 'Clase 4 · Seguimiento farmacoterapéutico y farmacovigilancia', 5, 'video', 10, TRUE)
  RETURNING id INTO v_clase;
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 0, '{"tone":"info","title":"En esta clase","html":"<p>Ejecuta el seguimiento con ACT, CAT, mMRC, exacerbaciones, uso de SABA y corticoide oral, técnica y adherencia.</p><p><strong>Objetivo:</strong> Ejecutar el seguimiento farmacoterapéutico de pacientes con asma y EPOC con indicadores medibles.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'video', 1, '{"source":"enlace","url":"https://www.youtube.com/watch?v=sku1rprc2Pk","provider":"youtube","videoId":"sku1rprc2Pk","title":"Seguimiento Farmacoterapéutico o SFT","transcriptHtml":""}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 2, '{"text":"La clase en texto","level":2}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'texto', 3, '{"html":"<p>El seguimiento farmacoterapéutico es una actividad del servicio farmacéutico (Decreto 780 de 2016 y Resolución 1403 de 2007) en la que el QF evalúa de forma sistemática la necesidad, efectividad y seguridad de los medicamentos, identifica problemas relacionados con medicamentos y acuerda intervenciones con el paciente y el médico.</p><p>Herramientas de evaluación:</p><ul><li><strong>Asma:</strong> preguntas de control de síntomas de GINA (síntomas diurnos más de dos veces por semana, despertares nocturnos, uso de rescate, limitación de actividad) y el Test de Control del Asma (ACT), que la GPC colombiana sugiere aplicar al menos una vez al año. GINA 2026 incorporó el CAAT y describió el Peds-AIRQ para niños.</li><li><strong>EPOC:</strong> escala de disnea mMRC y cuestionario CAT, número de exacerbaciones moderadas o graves.</li><li><strong>Ambos:</strong> técnica inhalatoria, adherencia (registros de dispensación), inhaladores de rescate por año, ciclos de corticoide oral, consultas a urgencias, hospitalizaciones, efectos adversos y vacunación.</li></ul><p><strong>Proceso sugerido:</strong> (1) entrevista inicial y estado de situación; (2) evaluación e identificación de problemas (por ejemplo, inefectividad por mala técnica, inseguridad por interacción, necesidad de un ICS no formulado); (3) plan de intervención acordado; (4) seguimiento a las 4-8 semanas; (5) registro de resultados.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 4, '{"tone":"consejo","title":"Ejemplo aplicado","html":"<p>En un programa de una EPS en Cúcuta, el QF registra en una hoja de seguimiento para cada paciente con asma: ACT, inhaladores de SABA por año, ciclos de corticoide oral y técnica. A los seis meses presenta al comité que el porcentaje de pacientes con 3 o más inhaladores de SABA al año bajó y que aumentaron los pacientes con técnica correcta.</p>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'destacado', 5, '{"tone":"importante","title":"Puntos clave","html":"<ol><li><strong>El seguimiento usa indicadores medibles:</strong> ACT o CAT, exacerbaciones, SABA por año y corticoide oral.</li><li>Cada problema detectado se convierte en una intervención acordada y registrada.</li><li>El seguimiento está respaldado por la normativa del servicio farmacéutico en Colombia.</li></ol>"}'::jsonb);
  INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
  VALUES (v_clase, 'encabezado', 6, '{"text":"Para profundizar","level":2}'::jsonb);
