  VALUES (v_clase, 'enlace', 11, '{"url":"https://normograma.invima.gov.co/normograma/compilacion/docs/resolucion_invima_15321_2024.htm","title":"Resolución 2024015321 de 2024 (INVIMA): contenido y periodicidad de los reportes de eventos adversos (vigente desde 1-mar-2025) (2024-04-08)","description":"Documento · Documento oficial · autoridad sanitaria"}'::jsonb);
